from pathlib import Path
import json, uuid, hashlib

ROOT = Path('/home/enpasos/projects/skillpilot')
BASE = Path(__file__).resolve().parent
INPUT = json.loads((BASE / 'whole-forty-current-E-goals-and-valid-native-P81-cases.byte-exact-input-successor.json').read_text())
ROWS = INPUT['whole40GoalProfileCases']
GOALS = {a['goalId']: a for a in ROWS}
MATERIALS = []
AUTHOR_ROWS = []

def gid(prefix):
    matches = [a for a in GOALS if a.startswith(prefix)]
    assert len(matches) == 1, prefix
    return matches[0]

def put(name, data):
    p = BASE / name
    assert not p.exists(), p
    p.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n')
    json.loads(p.read_text())

def add(key, title, title_en, description, description_en, material, material_en, tasks, sources=None):
    # Each task tuple gives one genuinely used current performance contract.
    # The shared dossier creates an integrated endpoint, not readiness coverage.
    ids = [gid(t[0]) for t in tasks]
    assert len(set(ids)) == len(ids) and 4 <= len(ids) <= 8
    score = len(tasks) * 6
    threshold = (score * 3 + 4) // 5
    introduction = '**Material und Auftrag**\n\n' + material.strip() + '\n\n**Aufgaben – ' + str(score) + ' BE**\n'
    introduction_en = '**Material and assignment**\n\n' + material_en.strip() + '\n\n**Tasks – ' + str(score) + ' points**\n'
    solution, solution_en, steps, performance = [], [], [], []
    for n, (prefix, task, task_en, answer, answer_en, rubric, rubric_en) in enumerate(tasks, 1):
        introduction += '\n' + str(n) + '. ' + task + ' **6 BE**\n'
        introduction_en += '\n' + str(n) + '. ' + task_en + ' **6 points**\n'
        solution.append(str(n) + '. ' + answer + '\n\n**Bewertung – 6 BE:** ' + rubric)
        solution_en.append(str(n) + '. ' + answer_en + '\n\n**Scoring – 6 points:** ' + rubric_en)
        steps.append({'id': 's' + str(n), 'points': 6, 'description': rubric})
        performance.append({'goalId': gid(prefix), 'wholeCurrentGoal': GOALS[gid(prefix)]['wholeCurrentCanonicalGoal'], 'taskNumber': n, 'actualTaskDemandDe': task, 'actualExpectedPerformanceDe': answer, 'minimalRequiresReason': 'Diese Leistung wird im angegebenen Material tatsächlich verlangt und mit sechs eigenen BE fachlich bewertet; bloße Themenbereitschaft wird nicht ergänzt.', 'rubricDe': rubric, 'rubricEn': rubric_en})
    goal = {
        'id': str(uuid.uuid5(uuid.NAMESPACE_URL, 'https://skillpilot.app/curriculum/DE/Gymnasium/wirtschaft/E40/2026-10-09/' + key)),
        'title': title, 'titleEn': title_en,
        'description': description, 'descriptionEn': description_en,
        'weight': 1, 'tags': ['GK', 'LK', 'Practice', 'Assessment'],
        'contains': [], 'requires': ids,
        'dimensionTags': {'framework': 'canonical-gymnasium-economics', 'demandLevel': 'AB3', 'phase': 'E'},
        'phase': 'E', 'type': 'atomic',
        'extendedData': {'applicabilityFromRequires': True},
        'examData': {
            'reviewStatus': 'draft', 'coveredGoalIds': ids,
            'coveredStrands': ['WW_RECHT', 'WW_GESELLSCHAFT', 'WW_POLITIK'] if key == 'youth-public-law' else ['WW_WIRTSCHAFT'] if key in ['finance-liability-and-spreadsheet-accounts', 'actual-team-company-data-project'] else ['WW_WIRTSCHAFT', 'WW_GESELLSCHAFT'] if key == 'production-innovation-and-career-exploration' else ['WW_GESELLSCHAFT', 'WW_POLITIK', 'WW_WIRTSCHAFT'],
            'demandLevels': ['AB1', 'AB2', 'AB3'],
            'taskContent': introduction, 'taskContentEn': introduction_en,
            'solutionContent': '\n\n'.join(solution) + '\n', 'solutionContentEn': '\n\n'.join(solution_en) + '\n',
            'scoring': {'maxPoints': score, 'passingPoints': threshold, 'steps': steps},
        },
    }
    assert goal['requires'] == goal['examData']['coveredGoalIds']
    MATERIALS.append(goal)
    AUTHOR_ROWS.append({'examGoalId': goal['id'], 'key': key, 'actualCurrentCourseMembershipOfAllCoveredGoals': 'GK+LK', 'actualAssessedGoals': performance, 'thirdPartySources': sources or [], 'ownMaterialLicense': 'CC-BY-4.0', 'author': '/root/economics_independent_continuation_a', 'authorStatus': 'draft candidate', 'independentWholeMaterialApproval': False, 'humanReview': 'pending', 'ownDOrVApproval': False})
    put('whole-' + key + '.DRAFT-terminal-goal.candidate.json', goal)

add('care-education-and-role-change',
    'E: Betreuung, Bildung und Rollenwandel materialgestützt beurteilen',
    'E: assess care, education and changing roles using a dossier',
    'Die lernende Person kann aus einem fiktiven kommunalen Dossier Familien- und Bildungswandel analysieren, politische und sozialstaatliche Antworten vergleichen und deren Gleichstellungswirkungen mit Bedingungen und Grenzen beurteilen.',
    'The learner can analyse changes in family and education from a fictional municipal dossier, compare political and welfare responses, and assess their equality effects with conditions and limitations.',
    '''Alle Daten, Stimmen und Programme betreffen die erfundene Gemeinde Lindenfeld. Sie sind keine deutsche Zeitreihe und keine Wirksamkeitsstudie. In zwei gleich abgegrenzten Erhebungen unter jeweils 100 Haushalten mit Schulkindern steigt die Zahl der Einpersonenerziehungs-Haushalte von 20 auf 30; die Zahl der Haushalte mit zwei erwerbstätigen betreuenden Erwachsenen steigt von 25 auf 40. Die Gruppen überschneiden sich nicht. Gewünschte Betreuung nach 16 Uhr: 20 bzw. 45 Haushalte; tatsächlich nutzbare Nachmittagsplätze jeweils 25. Unter jeweils 100 Schulabgängern steigt die Zahl höherer Abschlüsse von 40 auf 55; in einer gleich abgegrenzten einkommensarmen Teilgruppe von 20 Personen von 4 auf 7. Abschlüsse und spätere Berufsverläufe werden nicht gleichgesetzt.

Programm A finanziert 20 zusätzliche bezahlbare Plätze bis 18 Uhr, benötigt jedoch qualifiziertes Personal. Programm B gibt 45 Haushalten einen gleich hohen Gutschein für bestehende Betreuungsangebote; deren Platzzahl und Öffnungszeiten ändern sich zunächst nicht. Gleiche öffentliche Gesamtkosten sind im Modell vorgegeben. Ein Bildungsprogramm stellt Leihgeräte und Lernberatung bereit; bisher fehlten 12 von 100 Schulkindern Geräte und 18 Kindern Unterstützung beim digitalen Lernen. Überschneidungen sind unbekannt.

Zwei fiktive Arbeitszeugnisse aus verschiedenen Modellzeitpunkten zeigen einen Rollenwandel: früher wurde Sorgearbeit allein Müttern zugeschrieben; heute werden Betreuungszuständigkeiten individuell vereinbart. Ein örtlicher Betrieb ersetzt informelle Beförderung nach dauernder Abendanwesenheit durch veröffentlichte Fachkriterien und planbare Gesprächstermine. Es liegen noch keine Ergebnisdaten zu Beförderungen vor.''',
    '''All data, voices and programmes concern the invented municipality Lindenfeld, not a German time series or an impact study. In two equally defined samples of 100 households with schoolchildren, single-carer households rise from20 to30 and households with two employed caring adults from25 to40; the groups do not overlap. Demand for care after4pm rises from20 to45 households; usable afternoon places remain25. Among100 school leavers, higher qualifications rise from40 to55; among a consistently defined low-income subgroup of20, from4 to7. Qualifications are not later career outcomes.

Programme A funds20 additional affordable places until6pm but needs qualified staff. Programme B gives45 households equal vouchers for existing care; place numbers/opening hours initially stay unchanged. Public total costs are stipulated equal. An education programme provides loan devices and learning guidance;12 of100 children lacked devices and18 lacked support, with overlap unknown.

Two fictional work documents from different model periods show a change from assuming mothers alone provide care to individually agreed responsibilities. A firm replaces informal promotion based on constant evening presence with published competence criteria and planned meetings. Promotion outcomes have not yet been measured.''',
    [
        ('c4c5bae8', 'Beschreiben Sie zwei Veränderungen der Familien-/Betreuungsstrukturen und die Bildungsentwicklung einschließlich Teilgruppe. Leiten Sie zwei institutionelle Folgen ab und nennen Sie eine Datenbegrenzung.', 'Describe two changes in family/care structures and the education trend including the subgroup. Derive two institutional implications and identify a data limitation.', 'Einpersonenerziehung steigt um10 Prozentpunkte, doppelte Erwerbstätigkeit um15; später Betreuungsbedarf steigt bei unverändertem Angebot. Höhere Abschlüsse steigen insgesamt40→55%, in der Teilgruppe20→35%, ohne daraus gesicherte Berufschancen zu machen. Betreuung und Schule benötigen passende Zeiten, zugängliche Unterstützung und gegebenenfalls Kapazität. Die Stichproben beweisen weder schlechtere Familienqualität noch Ursache des Bildungswandels; unbekannte Überschneidung verbietet das Addieren von Geräte-/Unterstützungsmängeln.', 'Single-care households rise10 percentage points and dual employment15; later care demand increases without more places. Higher qualifications rise40to55% overall and20to35% in the subgroup without proving career outcomes. Institutions may need suitable opening hours, accessible support and capacity. Samples prove neither family quality nor causes; unknown overlap prevents adding device/support shortages.', 'Zwei konkrete Familien-/Bedarfsänderungen2; Gesamt- und Teilgruppenbildung mit Bezugsgrößen2; zwei fachlich abgeleitete institutionelle Folgen und eine zutreffende Grenze2.', 'Two concrete family/demand changes2; overall/subgroup education with denominators2; two justified institutional implications and a valid limitation2.'),
        ('77edbcf9', 'Erläutern Sie, wie Programm A auf sozialen Wandel reagiert. Prüfen Sie seinen Wirkungsweg und zwei Umsetzungsbedingungen, statt die gewünschte Wirkung als bewiesen darzustellen.', 'Explain how programme A responds to social change. Examine its mechanism and two implementation conditions without treating intended effects as proven.', 'Das Programm antwortet auf Erwerbs-/Betreuungszeitwandel mit zusätzlich verfügbarem öffentlichem Angebot und längeren Zeiten. 25+20=45 Plätze könnten die45 Modellbedarfe zahlenmäßig erreichen, wenn die Plätze tatsächlich nutzbar sind. Passendes Personal, bezahlbarer Zugang und Zeit-/Ortsübereinstimmung sind Bedingungen; freiwillige Nutzung und individuelle Lebensformen bleiben verschieden. Eine Zahlenübereinstimmung beweist keine realisierten Wirkungen.', 'The programme responds to changed work/care schedules with more available public provision and longer hours.25+20=45 places could meet45 stated needs numerically if usable. Staff, affordability and matching times/locations are conditions; use and family preferences vary. Equal totals do not prove realised effects.', 'Wandel und konkreter politischer Antwortbezug2; nachvollziehbarer Angebots-/Teilhabemechanismus2; zwei Bedingungen plus Trennung von Möglichkeit und belegtem Ergebnis2.', 'Change and specific political response2; coherent provision/participation mechanism2; two conditions and distinction between potential and demonstrated outcome2.'),
        ('af772e72', 'Vergleichen Sie A und B nach Kapazität, Zugang und Zielgenauigkeit. Begründen Sie unter den gegebenen Bedingungen eine Priorität und einen Gegenaspekt.', 'Compare A and B by capacity, access and targeting. Justify a priority under the stated conditions and a counterconsideration.', 'A erweitert Angebot und Zeiten; B erleichtert Bezahlung vorhandener Plätze, löst aber die45-zu25-Kapazitätslücke und starre Zeiten allein nicht. A ist bei belegtem Spätbedarf vorrangig, sofern Personal verfügbar ist. B kann vorhandene teure Plätze zugänglicher machen und schneller wirken, sofern geeignete Plätze bestehen. Gleiches Budget ersetzt keine Prüfung, welche Haushalte mit welchen Bedarfen erreicht werden.', 'A expands supply and hours; B helps pay for existing places but alone does not resolve45needs against25places or fixed hours. A is a priority for stated late demand if staff are available. B could rapidly improve access to suitable expensive existing places. Equal budgets do not show which needs are reached.', 'Unterschied Geldtransfer/Angebotsausbau2; fallbezogene Kapazitäts-, Zugangs- und Zielgenauigkeitsprüfung2; begründete bedingte Priorität mit Gegenaspekt2.', 'Distinguish transfer from expanded service2; case-specific capacity/access/targeting2; justified conditional priority and counterconsideration2.'),
        ('0eaf70cd', 'Vergleichen Sie die familienpolitische Antwort A mit dem Bildungsprogramm: Welchen unterschiedlichen Bedarf bearbeitet jede Maßnahme, wie kann sie wirken und was bleibt offen?', 'Compare family-policy response A with the education programme: which distinct need does each address, how could it work, and what remains uncertain?', 'A bearbeitet Vereinbarkeit über Zeit und Betreuungskapazität; das Bildungsprogramm bearbeitet materiellen Lernzugang und pädagogische Unterstützung. Geräte und Beratung sind komplementäre Hilfen, nicht dieselbe Leistung;12 und18 können sich überschneiden. Beide Programme benötigen tatsächlich verfügbare passende Angebote. Weder Ausgabe von Geräten noch neue Platzzahlen allein beweisen Lern-/Familienerfolg; Nutzungs- und Ergebnisdaten fehlen.', 'A addresses combining work and care through time and capacity; education support addresses material access and learning assistance. Devices and guidance are complementary, not identical;12 and18 may overlap. Both need suitable available services. Device distribution or place counts alone prove neither learning nor family outcomes; use/outcome data are missing.', 'Zwei unterschiedliche familien-/bildungspolitische Bedarfe2; zwei zutreffende materialbezogene Wirkungswege2; Komplementarität/Überschneidung und Ergebnisgrenze2.', 'Two distinct family/education needs2; two accurate case-based mechanisms2; complementarity/overlap and outcome limitation2.'),
        ('3ac589b5', 'Analysieren Sie den Rollenwandel und die neue Beförderungspolitik. Beurteilen Sie die mögliche Gleichstellungswirkung anhand zweier Kriterien und benennen Sie erforderliche Ergebnisdaten.', 'Analyse the changing roles and promotion policy. Assess potential equality effects using two criteria and identify needed outcome data.', 'Die Dokumente verändern normative Erwartungen von geschlechtsgebundener zu individuell vereinbarter Sorgearbeit. Veröffentlichte Fachkriterien und planbare Termine können eine zeitliche/informelle Zugangshürde mindern und vergleichbare Leistungen nachvollziehbarer behandeln. Kriterien sind etwa gleicher Zugang und Vereinbarkeit; Wirkung hängt von tatsächlicher Anwendung und verfügbaren Terminen ab. Daten zu Bewerbungen, vergleichbaren Anforderungen und Beförderungen werden benötigt. Keine angeborene Eignung oder einheitliche Interessen eines Geschlechts werden unterstellt.', 'The documents shift normative expectations from gender-assigned to individually agreed care. Published competence criteria and planned meetings may reduce informal/time barriers and improve comparable treatment. Access and combining care/work are suitable criteria; application and available times matter. Applications, comparable requirements and promotion outcomes are needed. No innate fitness or uniform gender interests are assumed.', 'Dokumentbezogener Rollen-/Normwandel2; Mechanismus der konkreten Gleichstellungsmaßnahme2; zwei Kriterien, passende Ergebnisdaten und Verzicht auf stereotype Zuschreibung2.', 'Document-based change in roles/norms2; specific equality mechanism2; two criteria, suitable outcome data and no stereotypical attribution2.'),
    ])

add('environment-wealth-and-frameworks',
    'E: Umweltkonflikte, Wohlstand und Unternehmensregeln beurteilen', 'E: assess environmental conflict, prosperity and business rules',
    'Die lernende Person kann in einem fiktiven Industriegebiet Umweltpositionen analysieren, Nachhaltigkeitsansätze und Wohlstandsindikatoren unterscheiden und die Wirkung staatlicher Rahmenbedingungen auf unternehmerische Optionen beurteilen.',
    'The learner can analyse environmental positions in a fictional industrial area, distinguish sustainability approaches and prosperity indicators, and assess how public frameworks affect business options.',
    '''Dossier zur erfundenen Region Talgrund. Alle Modellzahlen und Regeln sind erfunden. Anwohner nennen gesundheitliche Belastung durch örtliche Abgase; eine gültige lokale Messreihe zeigt Belastung über dem im Modell festgelegten Grenzwert. Betriebe befürchten Kosten und verweisen auf Aufträge; konkrete Umsatzverluste sind nicht gemessen. Der Gemeinderat diskutiert eine bindende Abgas-Mindestregel ab nächstem Modelljahr. Filter F kostet10.000 EUR plus500 EUR jährlich; Prozessänderung P kostet12.000 EUR und spart300 EUR jährlich gegenüber dem bisherigen Verfahren. Beide erfüllen nach der Modellregel denselben Abgasstandard. Finanzierung, Betriebsdauer und Ausfallrisiken sind noch zu prüfen. Es wird keine reale Genehmigung beurteilt.

Drei weitere Nachhaltigkeitspositionen: E verbessert die Energieeffizienz von10 auf8 kWh pro Stück und steigert die Modellproduktion von100 auf125 Stück; S reduziert unnötige Produktion von100 auf95 Stück bei10 kWh; K führt Materialien im geeigneten geschlossenen Kreislauf zurück. Ein weiteres Werk senkt Energieverbrauch und erhöht Gewinn, verschlechtert aber nach Fallannahme Arbeitsbedingungen. Eine vollständige Ökobilanz liegt nicht vor.

Zwei erfundene Vergleichsregionen im gleichen Jahr: A hat kaufkraftbereinigtes BIP pro Kopf40.000 Rechnungseinheiten, HDI0,84 und12 Tonnen jährliche CO2-Emissionen pro Kopf; B35.000, HDI0,92 und7 Tonnen. BIP bezeichnet Produktion, nicht die konkrete Verteilung auf Haushalte. Der HDI kombiniert Gesundheit, Bildung und Lebensstandard; er misst weder alle Ungleichheiten noch Umweltwirkungen. Diese Kurzdefinition folgt sinngemäß [UNDP, HDI](https://hdr.undp.org/data-center/human-development-index); sämtliche hier genannten Werte sind fiktiv.''',
    '''Dossier for the invented Talgrund region; all figures/rules are fictional. Residents identify health burdens from local exhaust; valid local measurements exceed a stipulated model limit. Firms fear costs and refer to orders, but revenue losses are unmeasured. A binding minimum exhaust standard is proposed for the next model year. Filter F costsEUR10,000 plus500annually; process P costs12,000 and saves300annually relative to the old process. Both meet the same model exhaust standard. Finance, operating horizon and failure risk remain open; no real permit is assessed.

Sustainability positions: E lowers energy per item10to8kWh while output rises100to125items; S reduces unnecessary output100to95at10kWh; K returns suitable materials through a closed cycle. Another plant lowers energy use/profits rise, but working conditions worsen by assumption. No complete life-cycle assessment is supplied.

Two invented comparable regions in the same year: A has purchasing-power-adjusted GDP per capita40,000units, HDI0.84 and annual CO2 per capita12tonnes; B35,000,0.92,7. GDP measures production, not household distribution. HDI combines health, education and living standards, not all inequality/environmental outcomes, following a short paraphrase of [UNDP](https://hdr.undp.org/data-center/human-development-index). All values are fictional.''',
    [
        ('b7633a54', 'Analysieren Sie die politische Umweltdebatte nach Akteuren, Interessen, Sach-/Wertargumenten und Verteilung der Lasten. Welche Kompromissfrage bleibt auch bei gleichem Abgasstandard offen?', 'Analyse the environmental debate by actors, interests, factual/value arguments and burdens. Which compromise issue remains even with equal exhaust standards?', 'Gesundheitsschutz und unternehmerische Kosten/Handlungsfähigkeit sind unterschiedliche konkrete Interessen. Die Messreihe belegt die Modellgrenzwertüberschreitung; ungemessene Umsatzverluste bleiben Prognosen. Gewichtung von Gesundheit, Beschäftigung oder Kosten ist normativ; nicht alle Aussagen sind gleichermaßen Messbefunde. Finanzierung und zeitliche Lasten, öffentliche Unterstützung oder gestufte Umsetzung können Konfliktpunkte sein; gleicher Standard entscheidet ihre Verteilung nicht.', 'Health and firms\' costs/viability are distinct interests. Measurements demonstrate the model exceedance; unmeasured revenue losses are forecasts. Weighting health, employment or costs is normative. Finance, timing, support or phased implementation may be compromise questions; equal standards do not settle burdens.', 'Akteure/Interessen mit Materialbezug2; Sachbefund, Prognose und Wertgewichtung getrennt2; konkrete Lasten-/Kompromissfrage mit Grenze2.', 'Case-based actors/interests2; separate factual findings, forecasts and values2; concrete burden/compromise issue with limitation2.'),
        ('ee36cbaf', 'Ordnen Sie E, S und K unterschiedlichen Nachhaltigkeitsansätzen zu und vergleichen Sie ihre Hebel. Prüfen Sie den Energiebeitrag von E und beurteilen Sie das Werk mit verschlechterten Arbeitsbedingungen über drei Dimensionen.', 'Classify E, S and K by sustainability approach and compare their mechanisms. Check E\'s energy contribution and assess the plant with worse conditions across three dimensions.', 'E=Effizienz je Leistung, S=Suffizienz beim Umfang, K=Konsistenz durch Materialkreislauf. E spart20% je Stück, verbraucht insgesamt jedoch vorher100×10=1.000 und nachher125×8=1.000 kWh; kein Gesamt-Energiegewinn ist damit bewiesen. S benötigt950 kWh unter der gegebenen Grenze. Energie-/Gewinnverbesserung sind ökologische/ökonomische Teilaspekte, schlechtere Arbeitsbedingungen ein sozialer Konflikt. Kreislauf oder niedrige Energiekosten allein beweisen keine umfassende Nachhaltigkeit.', 'E=efficiency per service, S=sufficiency in volume, K=consistency through material cycles. E saves20%per item but totals1,000kWh before/after(100×10;125×8), not a demonstrated total reduction. S uses950kWh under the assumption. Energy/profit improvements are environmental/economic aspects while worse conditions create a social conflict. Cycles or cheap energy alone prove no comprehensive sustainability.', 'Drei Ansätze und unterschiedliche Hebel2; korrekte Stück-/Gesamtbezug-Prüfung2; drei Dimensionen und begründete Nachhaltigkeitsgrenze2.', 'Three approaches/distinct levers2; correct unit/total check2; three dimensions and justified sustainability limitation2.'),
        ('5262a0ba', 'Interpretieren Sie BIP, HDI und Emissionen für A/B. Beurteilen Sie die Aussage „A ist in jeder Hinsicht wohlhabender; alle Haushalte profitieren“. Geben Sie einen ergänzenden Informationsbedarf an.', 'Interpret GDP, HDI and emissions for A/B. Assess “A is more prosperous in every respect and all households benefit”. Identify further needed information.', 'A hat höhere durchschnittliche Produktion, B höhere zusammengefasste menschliche Entwicklung und geringere gegebenenfalls schädliche Klimabelastung je Kopf. Verschiedene Messgegenstände erlauben diese Kombination; HDI enthält unter anderem Einkommensdimension, ist aber kein BIP-Ranking. Durchschnittswerte beweisen keine Haushaltsverteilung und Emissionen allein keine gesamte Umweltlage. Verteilungs-, Gesundheits-/Bildungsdetails und weitere Umwelt-/Zeitdaten sind passende Ergänzungen.', 'A has higher average production, B higher summary human development and lower stated per-capita climate burden. Different measures allow this combination; HDI includes income but is not a GDP ranking. Averages do not establish household distribution; emissions alone are not a complete environmental picture. Distribution, health/education detail and other environmental/time data are useful.', 'Drei Messgegenstände und konkrete A/B-Interpretation2; differenziertes Wohlstandsurteil statt Ranglistenverwechslung2; Aggregat-/Verteilungsgrenze und geeignete Ergänzung2.', 'Three measures and specific A/B interpretation2; differentiated prosperity assessment2; aggregate/distribution limitation and suitable extra information2.'),
        ('65d9f38e', 'Beurteilen Sie, wie die Modellregel Handlungsoptionen des Betriebs verändert. Vergleichen Sie F/P nach öffentlichem Ziel, Kapitalbedarf und laufenden Kosten und formulieren Sie eine bedingte Entscheidung mit zwei weiteren Prüfangaben.', 'Assess how the model rule changes the firm\'s options. Compare F/P by public aim, investment and running cost, giving a conditional decision with two additional checks.', 'Die bindende Mindestregel setzt zulässige Optionen unter gleichem Umweltziel; sie verlangt Finanzierung, lässt aber Wahl F/P. F hat2.000 EUR weniger Anfangsbedarf; P verbessert laufenden Vergleich um800 EUR jährlich. Bei sonst gleichen Bedingungen gleichen2,5Jahre diesen Unterschied rechnerisch aus, ohne Diskontierung oder Risiko zu berücksichtigen. Dieser einfache Bezug ist optional, keine verlangte Investitionsrechenroutine. Wahl hängt von Kapitalzugang, verlässlich erwarteter Betriebsdauer und Kapazität/Risiko ab; Regeln sind weder nur Last noch Garantie privater Rentabilität. Das Modell wird nicht als geltendes deutsches Recht ausgegeben.', 'The binding minimum rule constrains feasible options under a common public aim while allowing F/P. F needs2,000less initially; P improves annual running-cost comparison by800. Under otherwise equal conditions2.5years arithmetically offsets this without discount/risk; that calculation is optional, not a separate required investment skill. Finance, reliable horizon and capacity/risk matter. Rules are neither only a burden nor guaranteed private profit; the model is not German law.', 'Verbindlicher Rahmen und öffentliche Ziele2; korrekter qualitativer Kapital-/Folgekostenvergleich2; bedingtes Urteil mit zwei konkreten Prüfangaben und Modell/Recht-Trennung2. Die optionale2,5-Jahresrechnung ist keine zusätzliche Bestehensbedingung.', 'Binding framework/public aims2; correct qualitative initial/running cost comparison2; conditional judgment with two checks and model/law distinction2. Optional2.5-year arithmetic is not an added passing condition.'),
    ], [{'title':'UNDP: Human Development Index, current definition actually read2026-10-09', 'url':'https://hdr.undp.org/data-center/human-development-index', 'use':'Short own paraphrase of dimensions/limits; invented region values, no third-party ranking.'}])

add('finance-liability-and-spreadsheet-accounts',
    'E: Finanzierung, Haftung und Finanzdarstellung einer Werkstatt prüfen', 'E: examine workshop finance, liability and financial charts',
    'Die lernende Person kann in einem fiktiven Werkstattfall Eigen-/Fremdfinanzierung und Kapitalgeberrechte unterscheiden, Haftungsrisiken kritisch abwägen und GuV-/Kapitalstrukturdaten mit einer tatsächlich datenverknüpften Tabellenkalkulation adressatengerecht darstellen.',
    'The learner can distinguish equity/debt finance and providers\' rights in a fictional workshop case, critically assess liability risk and create audience-appropriate, data-linked spreadsheet charts from income-statement and funding data.',
    '''Die erfundene Reparatur-GmbH R braucht90.000 EUR. Vertrag E:30.000 EUR Eigenkapitaleinlage, vereinbartes Stimmrecht und Ausschüttung nur bei entsprechendem Beschluss/Erfolg; kein fester Rückzahlungstermin. Vertrag K:60.000 EUR Kredit, vereinbarter Zins und jährlich insgesamt12.000 EUR Zins/Tilgung; kein Stimmrecht. Vor diesem Schuldendienst sind im Planszenario18.000 EUR, im schwachen Szenario9.000 EUR Zahlungsmittelüberschuss vorhanden. Diese Zahl ist kein GuV-Gewinn. Die Gesellschafterhaftung ist grundsätzlich auf Gesellschaftsvermögen begrenzt; zusätzlich verpflichtet sich eine Gesellschafterin im vorgegebenen wirksamen Bürgschaftsvertrag gegenüber der Bank für genau diesen Kredit einzustehen. Andere Haftungstatbestände werden nicht geprüft. Die Grundunterscheidung folgt sinngemäß [§13 GmbHG](https://www.gesetze-im-internet.de/gmbhg/__13.html) und [§765 BGB](https://www.gesetze-im-internet.de/bgb/__765.html).

Für neue Auszubildende sind GuV-Daten in Tausend EUR gegeben: Jahr2022/2023/2024; Umsatz240/270/300; Gewinn18/21/12. Ein Korrekturlauf verändert nur Gewinn2024 von12 auf18. Für Lieferanten ist zusätzlich die Finanzierung am selben Stichtag gegeben: Vermögen90, Eigenkapital30, Schulden60; Vergleichsszenario Vermögen90, Eigenkapital45, Schulden45. Vermögen ist die Gegenseite und darf nicht als dritter Finanzierungsteil addiert werden. Erstellen Sie echte lokale Tabellenkalkulationsdateien mit datenverknüpften Grafiken und dokumentiertem Eingabewechsel; eine Textbehauptung ersetzt das Arbeitsprodukt nicht. Es sind nur fiktive Unternehmensdaten nötig.''',
    '''Invented repair company R needsEUR90,000. Equity contract E contributes30,000, gives agreed voting rights and distributions only following relevant decisions/results, without a fixed repayment date. Loan K supplies60,000, agreed interest and annual total interest/principal12,000 without votes. Cash available before debt service is18,000in the plan and9,000under stress; this is not accounting profit. Shareholder liability is normally limited to company assets, but one shareholder additionally gives a stipulated valid personal guarantee for this loan. Other liabilities are outside scope, following short paraphrases of [GmbHG13](https://www.gesetze-im-internet.de/gmbhg/__13.html) and [BGB765](https://www.gesetze-im-internet.de/bgb/__765.html).

Income-statement data for apprentices, EURthousands:2022/2023/2024 revenue240/270/300; profit18/21/12. Change only2024profit12to18. Supplier discussion: dated assets90 financed by equity30/debt60; alternative assets90/equity45/debt45. Assets must not be added as a third funding component. Produce actual local spreadsheet files, linked charts and evidence of the input change; prose alone does not replace the artefact. Only fictional firm data are needed.''',
    [
        ('e7fbbb64', 'Erläutern Sie die Finanzierungsmischung nach Kapitalart, Rückzahlung/Mitwirkung und Belastung der Zahlungsmittel. Trennen Sie Gewinn, Zahlungsmittelüberschuss und Haftung.', 'Explain the funding mix by capital type, repayment/participation and cash burden. Distinguish profit, cash surplus and liability.', 'E ist Beteiligung30.000/90.000=ein Drittel; K Fremdkapital zwei Drittel. E hat vorgegebene Mitwirkung und erfolgsabhängige Ausschüttung, K feste Zahlungs-/Rückzahlungsansprüche ohne Stimmrecht.12.000 Schuldendienst belasten Liquidität; Jahresgewinn ist eine andere Periodengröße. Kapitalart und Vertrag erklären Rechte; Haftung ist eine gesonderte Risikofrage, keine automatische Folge derselben Mittelhöhe.', 'E is one-third equity and K two-thirds debt. E has stated participation/conditional distributions; K fixed payment/repayment rights without votes.12,000debt service uses cash, while annual profit is a different period measure. Capital type/contract determine rights; liability is a separate risk question rather than a consequence of equal funding size.', 'Eigen-/Fremdkapital mit gegebenen Beträgen2; vertragliche Mitwirkung/Rückzahlung2; Liquiditäts-/Gewinn-/Haftungsunterscheidung2.', 'Equity/debt with given amounts2; contractual participation/repayment2; cash/profit/liability distinctions2.'),
        ('c4f27b51', 'Beschreiben Sie Pflichten und Ansprüche der zwei Kapitalgeber und trennen Sie bei Zahlungsschwierigkeiten Bankausfall, Beteiligungsverlust und Bürgschaftsrisiko.', 'Describe the two providers\' duties/claims and distinguish bank default, equity loss and guarantee risk during financial distress.', 'Eigenkapitalgeber leistet die vereinbarte Einlage und erhält vorgegebene Stimm-/bedingte Ausschüttungsrechte; Bank zahlt Kredit aus und besitzt Zins-/Rückzahlungsforderung ohne Stimmrecht. Die Bank kann Ausfall ihrer Forderung erleiden, die Beteiligung an Wert verlieren. Die zusätzliche wirksame persönliche Bürgschaft kann privates Vermögen belasten; das ist von normaler Gesellschaftshaftung und Beteiligungsverlust getrennt. Der Vertrag legt Umfang fest, nicht allein GmbH-Bezeichnung oder Kapitalsumme.', 'The equity provider contributes agreed funds and receives specified voting/conditional distribution rights; the bank advances the loan and has interest/repayment claims without votes. The bank may lose its claim and equity may lose value. An additional valid guarantee can expose personal assets, separate from normal company liability and equity loss; terms define scope.', 'Je passende Kapitalgeberpflicht und Ansprüche2; Bankforderungsausfall/Beteiligungsverlust getrennt2; zusätzliche eigene Verpflichtung und Vertragsgrenze2.', 'Suitable provider duties/claims2; distinguish default from equity loss2; additional personal obligation and contractual boundary2.'),
        ('4c7c7297', 'Diskutieren Sie Finanzierung und Haftung unter dem schwachen Szenario und bei einem Vergleichskredit ohne persönliche Bürgschaft. Geben Sie zwei begründete Prüf-/Handlungsoptionen ohne allgemeine Finanzierungsrangfolge an.', 'Discuss funding and liability under stress and a comparison loan without personal guarantee. Give two justified checks/options without a universal funding ranking.', 'Im Plan bleiben18.000−12.000=6.000, unter Stress fehlen12.000−9.000=3.000 EUR. Reserve, angepasster Rückzahlungsplan oder zusätzliche Eigenmittel bedürfen Vereinbarung/Passung; Eigenkapital kann Mitspracherechte verändern. Gleicher Kredit ohne persönliche Bürgschaft verändert nicht den Gesellschaftsschuldendienst, mindert aber genau das zusätzliche private Garantierisiko. Beteiligung und Bankforderung bleiben riskant. Liquiditätsplan, Bürgschaftsumfang, Kosten und Einfluss sind Prüfangaben, keine individuelle Anlageberatung.', 'Plan leaves6,000; stress creates3,000shortfall. Reserves, agreed revised repayment or extra equity need feasibility/agreements; equity can change influence. The same loan without guarantee retains company debt service but removes that particular personal guarantee exposure. Equity/loan default remain risky. Liquidity planning, guarantee terms, costs and control need scrutiny, not individual investment advice.', 'Plan-/Stressvergleich mit3.000-Lücke2; zwei materialbezogene Finanzierung-/Anpassungsabwägungen2; Bürgschaftsvariation fachlich getrennt und kein pauschales Rangurteil2.', 'Plan/stress comparison with3,000gap2; two case-based funding/adaptation considerations2; separate guarantee variation without blanket ranking2.'),
        ('685624a0', 'Erstellen Sie in einer Tabellenkalkulation für Auszubildende eine Grafik der GuV-Entwicklung und für Lieferanten eine Grafik der Kapitalstruktur. Begründen Sie Formen, Einheiten und Zielgruppenbezug. Führen Sie beide vorgegebenen Datenänderungen aus und dokumentieren Sie die Aktualisierung und Aussagegrenzen.', 'Create spreadsheet charts of the income-statement trend for apprentices and funding structure for suppliers. Justify form, units and audience fit. Carry out both stated data changes and document updating and limits.', 'Erforderlich sind tatsächlich verknüpfte Tabellen/Grafiken, nicht nur Beschreibungen. Zeitreihen benötigen Jahre/Tausend-EUR und erkennbaren Gewinn trotz größerem Umsatz, etwa getrennte abgestimmte Diagramme ohne versteckte Achsen. Anfangs steigt Umsatz, letzter Gewinn fällt; Wechsel12→18 muss Grafik aktualisieren. Kapitalstruktur30/60 von90 entspricht33,3/66,7%, danach50/50%; gestapelte Balken mit Bezugsgröße sind passend, Vermögen ist kein dritter Anteil. Stichtag ist keine Zeitreihe, Struktur beweist keine sichere Zahlungsfähigkeit und Reihen allein keine Ursachen.', 'Actual linked tables/charts are required. Trends need years/EURthousands and visible profit despite larger revenue, e.g. separate aligned charts without hidden scales. Revenue rises while final profit initially falls;12to18must update. Funding30/60of90 is33.3/66.7%, then50/50; a stacked bar with denominator is suitable and assets are not a third share. A date is not a time series, structure does not guarantee liquidity, and trends alone establish no causes.', 'Tatsächliche datenverknüpfte Datei und zwei fachlich passende, zielgruppenbezogene Grafiken2; beide sichtbar ausgeführten Eingabewechsel mit korrekter Bezugsgröße2; Zeit-/Bestands-/Gewinn-/Aussagegrenzen2. Ohne tatsächliche Datei bzw. äquivalent prüfbares Spreadsheet-Arbeitsprodukt höchstens2 von6.', 'Actual linked file and two accurate audience-appropriate charts2; both demonstrable input changes/correct denominators2; time/stock/profit/interpretive limits2. Without an actual file or equivalent verifiable spreadsheet artefact at most2of6.'),
    ], [{'title':'GmbHG13','url':'https://www.gesetze-im-internet.de/gmbhg/__13.html','use':'Short paraphrase, normal company liability only.'},{'title':'BGB765','url':'https://www.gesetze-im-internet.de/bgb/__765.html','use':'Short paraphrase, separately stipulated valid guarantee; no examination of formation/defences.'}])

add('production-innovation-and-career-exploration',
    'E: Produktion und Innovation mit Arbeitswelt und Berufserkundung verbinden', 'E: connect production and innovation with work and career exploration',
    'Die lernende Person kann Produktionsabläufe und digitale Unterstützung analysieren, Innovationswirkungen bedingt erklären und Arbeitsweltveränderungen sowie eigene berufliche Erkundungsmöglichkeiten anhand konkreter Tätigkeitsprofile beurteilen.',
    'The learner can analyse production workflows and digital support, explain conditional innovation effects and assess work changes and personal career exploration using concrete job profiles.',
    '''Die erfundene Möbelwerkstatt V fertigt individuelle Aufträge über Zuschnitt, Montage und Lackierung. Ein digitales Board zeigt Freigaben und Übergaben. Die Lackierung hat Engpässe; neue Sensordaten senken ungeplante Maschinenausfallstunden im kleinen Probelauf von80 auf56, erfordern aber Schulung. Absatz, Nettobeschäftigung und Umweltnettoeffekt sind unbekannt. Als Vergleich fertigt Betrieb L große Stückzahlen drei Möbelvarianten auf einer Linie; bei Wechseln ändern sich Programme/Materiallisten. Falsche Stammdaten erzeugten im Modell falsche Beschläge. Es liegen zwei unterschiedliche Organisationsformen mit ihren konkreten Bedingungen vor.

Arbeitsprofil angestellte Fachkraft: Auftrag prüfen, fachlich sichere Arbeit, Kundenfragen, Zusammenarbeit und Fristen. Selbstständige Werkstattführung zusätzlich: Akquise, Kalkulation, Finanzierung, Organisation und Gesamtverantwortung. Digitale Assistenz kann Informationen schnell finden; im Modell steigen gleichzeitig parallele Kundenanfragen und menschliche Fehlerprüfung bleibt nötig. Bildschirmplanung kann teils hybrid mit festen Kontaktzeiten erfolgen; Produktion benötigt Präsenz. Als datiertes Primärmaterial: BAuA-Kurzpublikation2025, DiWaBe2.0-Befragung2024, berichtet Zusammenhänge von KI-Nutzung mit mehr Handlungsspielraum und höherer Arbeitsintensität. Diese eigene Kurzfassung der [amtlichen Publikationsseite](https://www.baua.de/DE/Angebote/Publikationen/Bericht-kompakt/KI-unterstuetzte-Arbeit) ist kein Kausalnachweis oder allgemeine Arbeitsplatzprognose.

Wählen Sie für die berufliche Reflexion nur Interessen/Stärken, die Sie selbst nennen möchten, oder formulieren Sie eine ausdrücklich vorläufige Erkundungsperspektive. Keine intime Angabe, Eignungseinstufung oder echte Bewerbung wird verlangt.''',
    '''Invented furniture workshop V makes customised orders through cutting, assembly and coating. A digital board shows approvals/handoffs, but coating is constrained. A small sensor pilot reduces unplanned machine downtime80to56hours with added training needs; sales, net employment and net environmental effects are unknown. Comparison firm L uses a production line for large quantities of3 furniture variants, changing programmes/material lists; wrong master data caused wrong fittings. These are distinct organisational forms under specified conditions.

Employee profile: check orders, safe skilled work, customer questions, collaboration and deadlines. Self-employed management adds acquisition, costing, finance, coordination and overall responsibility. Digital assistance speeds information retrieval, but the fictional case also adds parallel enquiries and still requires human error checking. Screen planning can be hybrid with agreed contact times, production needs presence. Primary context: BAuA2025 publication reporting DiWaBe2.0 survey2024 associations of AI use with more discretion and greater work intensity, in an own short paraphrase of the [official publication page](https://www.baua.de/DE/Angebote/Publikationen/Bericht-kompakt/KI-unterstuetzte-Arbeit). This proves neither causation nor general job outcomes.

Select only interests/strengths you wish to discuss or state an explicitly tentative exploration perspective. No intimate disclosure, fitness classification or actual application is required.''',
    [
        ('2ccb9f7e', 'Vergleichen Sie V/L nach Arbeitsschritten, Arbeitsteilung und Produktionsgestaltung. Erklären Sie bei beiden Nutzen und Grenze der IT-Unterstützung und einen passenden Ansatz für den jeweiligen Engpass/Fehler.', 'Compare V/L by steps, division of labour and production layout. Explain benefits/limits of IT and one suitable response to each bottleneck/error.', 'V verbindet individuelle Aufträge über spezialisierte Werkstattstationen; L wiederholt Linienabläufe mit Variantenwechsel und Abstimmung. Das Board verbessert Übergaben/Freigaben, schafft aber keine Lackierkapazität. Linienprogramme koordinieren Material, benötigen richtige Stammdaten und Prüfung; digitale Steuerung ist nicht automatisch fehlerfrei. Kapazitäts-/Reihenfolgeprüfung bei V und Stammdaten-/Freigabeprüfung bei L bearbeiten die tatsächlichen Probleme.', 'V links custom work across specialised workshop stations; L repeats line processes with variants/change coordination. A board improves handoffs/approval without adding coating capacity. Programmes coordinate materials but require accurate master data/checking; IT is not automatically error-free. Capacity/scheduling checks for V and data/approval checks for L address actual issues.', 'Beide Abläufe und unterschiedliche Arbeitsteilung/Produktionsgestaltung2; konkreter IT-Nutzen und Grenze je Betrieb2; zwei problembezogene Ansätze mit Mechanismus2.', 'Both workflows/different labour-layout organisation2; specific IT benefits/limits in each2; two problem-related responses with mechanisms2.'),
        ('f90e4741', 'Analysieren Sie Wirkungswege der Sensorinnovation vom Betrieb zu Kunden, Beschäftigten und Wirtschaft. Verwenden Sie den Probelaufbefund und trennen Sie ihn von möglichen Nettoeffekten; nennen Sie zwei Zielkonflikte bzw. Bedingungen.', 'Analyse innovation pathways from the firm to customers, staff and the economy. Use the pilot finding while separating it from possible net effects; identify two trade-offs/conditions.', 'Ausfallstunden sinken24/80=30% im gegebenen Probelauf. Verfügbare Kapazität kann Lieferverlässlichkeit/Produktion unterstützen, sofern Nachfrage, Personal und Anschlussstationen passen. Schulung beansprucht Zeit/Kosten, neue Aufgaben können entstehen; weder mehr Absatz noch Arbeitsplatzabbau ist gemessen. Lackierengpass kann zusätzliche Kapazitätswirkung begrenzen. Nachfrage, Qualifikation, Verteilung der Vorteile und Netto-Umweltdaten sind Bedingungen; ein Pilot beweist keine gesamtwirtschaftliche Erfolgskette.', 'Pilot downtime falls24/80=30%. Capacity may improve reliability/output if demand, staff and downstream stations allow. Training consumes time/cost and changes tasks; increased sales or job losses are not measured. Coating can constrain gains. Demand, skills, benefit distribution and environmental data matter; a pilot is not proof of an economy-wide success chain.', 'Konkreter Probelaufbefund und korrekte Grenze2; zwei nachvollziehbare unternehmensübergreifende Wirkungswege2; zwei Bedingungen/Zielkonflikte ohne Netto-Erfolgs-/Beschäftigungsbehauptung2.', 'Concrete pilot finding and limitation2; two coherent wider pathways2; two conditions/trade-offs without invented net success/jobs2.'),
        ('9cb6bd3b', 'Beurteilen Sie Chancen/Risiken von digitaler Assistenz und hybrider Arbeit für zwei Tätigkeiten. Trennen Sie BAuA-Befragungsbefund von Modellannahmen. Leiten Sie einen konkreten Erkundungs-/Lernschritt für eine von Ihnen gewählte berufliche Orientierung ab.', 'Assess digital assistance/hybrid work for two activities. Separate BAuA survey findings from model assumptions. Derive a specific exploration/learning step for a chosen career perspective.', 'Amtlicher Kontext nennt Zusammenhänge von Handlungsspielraum/Intensität, keine gesicherte Ursache im Betrieb V. Assistenz kann Suche entlasten, parallele Anfragen und Prüfverantwortung jedoch belasten. Hybride Planung kann Pendeln/Flexibilität verbessern, benötigt Abgrenzung/Kommunikation; Präsenzproduktion besitzt andere Möglichkeiten. Ein begründeter eigener Schritt kann tatsächliche Aufgaben/Kontaktregeln erkunden oder fachliches Prüfen/Kooperation entwickeln. Keine pauschale Arbeitsplatz- oder Eignungsvorhersage.', 'The official context reports discretion/intensity associations, not a proven cause in V. Assistance may ease search but enquiries/checking can intensify work. Hybrid planning offers flexibility/less travel while needing boundaries/communication; on-site production differs. A reasoned personal step could examine actual tasks/contact rules or develop checking/collaboration. No blanket job or fitness prediction follows.', 'Zwei konkrete Chancen/Risiken verschiedener Tätigkeiten2; Befund/Fallannahme und Gestaltungsbedingungen getrennt2; begründeter persönlich gewählter Erkundungs-/Lernschritt ohne deterministisches Urteil2.', 'Two specific opportunities/risks across activities2; distinguish evidence/assumptions and design conditions2; justified self-chosen exploration/learning step without determinism2.'),
        ('96ab60e8', 'Vergleichen Sie Beschäftigten- und Selbstständigenprofil mit zwei freiwillig gewählten eigenen Interessen/Stärken. Benennen Sie eine Gemeinsamkeit, zwei zusätzliche Gründungsanforderungen, einen entwickelbaren Bereich und einen überprüfbaren nächsten Erkundungsschritt.', 'Compare employee/self-employed profiles with two voluntarily selected interests/strengths. Identify a shared demand, two additional founding demands, a developable area and a checkable exploration step.', 'Auftragsklärung, fachliche Sorgfalt und Zusammenarbeit sind gemeinsam; Akquise/Finanzierung/Gesamtverantwortung sind zusätzliche Anforderungen. Eigene Bezugspunkte müssen konkret mit Tätigkeiten verbunden werden; Bewertung betrifft die nachvollziehbare Reflexion, nicht welche Eigenschaft gewählt wurde. Ein entwickelbarer Bereich und tatsächliche Fragen bei einer freiwilligen Berufserkundung halten Möglichkeiten offen. Kreativität oder Zurückhaltung entscheidet keine Eignung, Interesse ist noch kein fachlicher Leistungsnachweis.', 'Order clarification, care and cooperation are shared; acquisition/finance/overall responsibility are additional. Selected personal points should connect to actual activities; reasoning is assessed, not the chosen trait. A developable skill and concrete voluntary exploration questions preserve options. Creativity/quietness determines no fixed fitness; interest is not proven competence.', 'Gemeinsame und zwei zusätzliche konkrete Anforderungen2; zwei freiwillige eigene Bezüge mit nachvollziehbarer Passung/Entwicklungsbedarf2; offener konkreter Erkundungsschritt ohne Eignungsstereotyp2.', 'Shared and two specific added demands2; two voluntary personal links with reasoned fit/development2; open concrete exploration step without fitness stereotypes2.'),
    ], [{'title':'BAuA: KI-unterstützte Arbeit,2025; DiWaBe2.0 survey2024','url':'https://www.baua.de/DE/Angebote/Publikationen/Bericht-kompakt/KI-unterstuetzte-Arbeit','use':'Own short paraphrase of actually read official publication landing page; PDF403 is not claimed as a whole-PDF read.'}])

add('actual-team-company-data-project',
    'E: Unternehmensdaten-Projekt tatsächlich durchführen und präsentieren', 'E: carry out and present an actual company-data project',
    'Die lernende Person kann ein abgegrenztes Wirtschaftsprojekt tatsächlich planen, in einer dokumentierten Team- oder Rollensimulation durchführen und auswerten, amtliche Unternehmensdaten mit Tabellenkalkulation analysieren sowie vollständige Präsentationsmaterialien adressatenbezogen prüfen.',
    'The learner can actually plan, execute and evaluate a bounded economics project through documented team work or role simulation, analyse official company data with spreadsheets and assess complete presentation materials for their audience.',
    '''Projektfrage: Welche begrenzten Hinweise liefert die deutsche Unternehmensstruktur für die Erkundung eines Berufs- oder Unternehmensfeldes im verarbeitenden Gewerbe oder Handel? Die amtlichen Angaben stammen aus Destatis, Statistisches Unternehmensregister, Berichtsjahr2024, Stand3.August2026, [Tabelle Unternehmen und abhängig Beschäftigte nach Wirtschaftsabschnitten](https://www.destatis.de/DE/Themen/Branchen-Unternehmen/Unternehmen/Unternehmensregister/Tabellen/stat-unternehmen-beschaeftigten-groessenklassen-wz08.html): Verarbeitendes Gewerbe198.362 Unternehmen/7.801.230 abhängig Beschäftigte; Handel einschließlich Kfz-Instandhaltung und Reparatur538.248/6.017.332. Zuordnung nach Tätigkeitsschwerpunkt/WZ2008. Unternehmen folgt statistischer Abgrenzung: Sitz Deutschland, Umsatzsteuervoranmeldungen und/oder Beschäftigte; in B–N nur Marktproduzenten, ohne Arbeitsgemeinschaften. Beschäftigte sind Jahresdurchschnittswerte von Beschäftigungsverhältnissen; Personen mit mehreren Verhältnissen können mehrfach nachgewiesen werden. Unternehmens- und Beschäftigtenzahlen sind keine individuellen Karrierechancen. Es wird kein Vergleich mit einem anders abgegrenzten Vorjahr verlangt.

Führen Sie das Projekt tatsächlich aus. Drei Rollen heißen nur Daten, Grafik und Redaktion; im kleinen Unterrichtsteam oder in ausdrücklich gekennzeichneter Rollenarbeit führen Sie jeden benötigten Schritt nachvollziehbar durch. Vier Arbeitsetappen: Fragestellung/Quellenprüfung → Berechnung → Tabellenkalkulationsgrafiken → Bericht/Präsentationsprüfung. Nach dem ersten Plan steht die Grafikrolle in Etappe2 nicht zur Verfügung; die Aufgabenverteilung muss begründet geändert werden. Verwenden Sie geeignete gemeinsame Datei-/Boardstrukturen ohne private Namen, Chatprotokolle oder Fremdkontakte. Abzugeben: ursprünglicher und geänderter Plan mit Verantwortlichkeiten, tatsächlich erzeugte verknüpfte Datendatei mit zwei beschrifteten Diagrammen, kurzer Entscheidungsbericht und konkrete Prozess-/Ergebnisreflexion. Bloße Behauptungen „durchgeführt“ ersetzen keine Artefakte.

Vollständige eigene fiktive Mini-Präsentation für Ausbildungssuchende, vier Folienblöcke:
1. Titel „Zwei Branchen, viele Möglichkeiten“. Aussage: „Wer kreativ ist, gehört in die Industrie.“
2. Tabelle mit Spalten „Branche“/„Unternehmen“: Verarbeitendes Gewerbe198.362, Handel538.248. Weitere Beschriftung fehlt; darunter „Mehr Firmen bedeutet sicher mehr Ausbildungsplätze für dich“.
3. Text: „Umsatz, ROI, EBITDA, strategische Synergien und operationalisierte KPIs machen uns erfolgreich.“ Keine Erläuterung oder Tätigkeitsbeispiele.
4. „Bewerbt euch sofort!“ Keine Aufgaben-/Qualifikations-/Arbeitsbedingungen und kein Quellenhinweis.
Fiktive Zuhörerrückmeldung: „Ich sehe zwei Zahlen, verstehe die Fachkürzel nicht und weiß nicht, welche Aufgaben oder Ausbildungsmöglichkeiten es gibt.“ Analysieren Sie diese gesamte Präsentation und verbessern Sie zwei gezielte Teile; die gegebene Rückmeldung beweist keine Wirkung auf alle Ausbildungssuchenden.''',
    '''Project question: what limited hints does German company structure give for exploring manufacturing or trade as a career/business field? Official Destatis business-register2024 data, dated3August2026, from [companies and dependent employment by industry](https://www.destatis.de/DE/Themen/Branchen-Unternehmen/Unternehmen/Unternehmensregister/Tabellen/stat-unternehmen-beschaeftigten-groessenklassen-wz08.html): manufacturing198,362companies/7,801,230dependent employment; trade including motor repair538,248/6,017,332. Classification is by main activity/WZ2008. Statistical firms have German seat and VAT returns and/or employment; B–N contains market producers only, excluding temporary consortia. Employment is an annual average of employment relationships; a person with several jobs may be counted repeatedly. Counts are not individual career chances; no differently defined prior-year comparison is required.

Actually execute the project. Three roles are labelled Data, Charts and Editing; use a small classroom team or explicitly labelled role simulation with transparent execution. Four stages: question/source checking → calculation → spreadsheet charts → report/presentation assessment. After the initial plan, the chart role is unavailable in stage2; justify a reassignment. Use suitable joint file/board structures without private names, chats or outside contact. Submit original/revised plans and responsibilities, an actual linked data file with2labelled charts, a brief decision report and specific process/outcome reflection. Assertions of completion do not replace artefacts.

Complete own fictional presentation for apprentices, four blocks:
1.“Two industries, many possibilities”:“Creative people belong in manufacturing.”
2.Table headed“Industry/Companies”:manufacturing198,362;trade538,248, with no other labels. Caption:“More firms guarantees more training places for you.”
3.“Revenue, ROI, EBITDA, strategic synergies and operationalised KPIs make us successful.”No explanations or job examples.
4.“Apply now!”No tasks, qualification/work conditions or source reference.
Fictional audience feedback:“I see two figures but do not understand the abbreviations or know what jobs/training are available.”Analyse the whole presentation and improve2specific parts. This feedback does not prove effects on all prospective apprentices.''',
    [
        ('596c02e3', 'Planen Sie die abgegrenzte Projektfrage, führen Sie die benötigten Daten-/Berichtsschritte tatsächlich durch und werten Sie Ergebnis und Methode aus. Unterscheiden Sie bereitgestellte amtliche Daten, eigene Berechnung und fiktive Unterrichtsbedingungen.', 'Plan the bounded question, actually execute data/report work and evaluate result/method. Distinguish official data, your calculation and fictional classroom conditions.', 'Prüfbar sind Fragestellung, realistischer Ablauf, entstandene Datendatei/Diagramme/Bericht und konkrete Auswertung. Bericht erläutert verschiedene Branchenstrukturen und begründet eine weitere Erkundungsfrage, keine automatische persönliche Gründungs-/Beschäftigungschance. Auswertung bezieht sich auf geleistete Arbeit, Quelle/Abgrenzung und Grenzen der Aggregation; Rollensimulation wird als solche bezeichnet. Ein Plan allein oder erfundene externe Durchführung genügt nicht.', 'Verifiable outputs are a bounded question, feasible workflow, actual data/charts/report and specific evaluation. The report explains differing industry structure and justifies further exploration, not automatic individual business/job success. Reflection concerns actual work, source/definitions and aggregate limitations; role simulation remains explicit. A plan alone or invented external execution is insufficient.', 'Abgegrenzte Frage und durchführbarer Plan2; tatsächliches fachliches Produkt mit dokumentierter Durchführung2; konkrete Ergebnis-/Methodenauswertung und Quellen-/Fiktionsgrenzen2. Ohne wirkliches Produkt/Ausführung höchstens2 von6.', 'Bounded question/feasible plan2; actual substantive product/documented execution2; specific outcome/method evaluation with source/fiction boundaries2. Without actual product/execution at most2of6.'),
        ('0d8cb18d', 'Wenden Sie Rollen, Abhängigkeiten und Änderungsmanagement im tatsächlichen Team-/Rollendurchlauf an. Dokumentieren Sie Abstimmung, geänderte Zuständigkeiten, Bearbeitungsstand und eine begründete digitale Medienwahl.', 'Apply roles, dependencies and change management in the actual team/role exercise. Document agreement, changed responsibilities, status and a justified digital-medium choice.', 'Datenprüfung geht Rechnung und Grafik voraus, Grafik/Analyse dem Bericht. Ausfall Grafikrolle führt zu nachvollziehbarer abgestimmter Vertretung oder zeitlicher Umplanung, ohne unfertige Daten als freigegeben zu behandeln. Ein gemeinsames versioniertes Dokument/Board macht Aufgaben, Status und Verantwortlichkeit sichtbar. Der dokumentierte Rollendurchlauf bzw. tatsächliche Beitrag zeigt Umsetzung; Toolnamen oder ein fertiger Plan ersetzen Koordination nicht. Evaluation nennt konkreten Gewinn und Grenze.', 'Checking precedes calculation/charts, analysis/charts precede report. The absent chart role requires agreed substitution/rescheduling, not treating unfinished data as approved. A versioned shared document/board makes tasks/status/responsibility visible. Actual role execution/contribution demonstrates implementation; tool names or a plan alone do not. Evaluation names a concrete benefit and limitation.', 'Rollen/Abhängigkeiten im ersten und geänderten Plan2; tatsächlich dokumentierte Abstimmung und Ausführung2; begründete Medienpassung mit konkreter Evaluation2. Ohne nachvollziehbaren Team-/Rollendurchlauf höchstens2 von6.', 'Roles/dependencies in initial/revised plans2; documented agreement/execution2; justified media fit and specific evaluation2. Without verifiable team/role execution at most2of6.'),
        ('8328f308', 'Analysieren Sie die amtlichen deutschen Unternehmensdaten. Erstellen Sie mit einer Tabellenkalkulation getrennte beschriftete Diagramme für Firmenzahl und Beschäftigungsverhältnisse, berechnen Sie Beschäftigungsverhältnisse je Unternehmen und begründen Sie eine begrenzte Schlussfolgerung für eine eigene Erkundung.', 'Analyse the official German firm data. Create separate labelled spreadsheet charts for firm counts/employment relationships, calculate employment per firm and justify a limited exploration conclusion.', 'Mehr Handelsunternehmen, aber mehr Beschäftigungsverhältnisse im verarbeitenden Gewerbe.7.801.230/198.362≈39,328 und6.017.332/538.248≈11,179; Mittelwerte sind weder Größe eines typischen Betriebs noch reine Personenzahlen. Diagramme bleiben datenverknüpft, nennen Jahr2024, Größen/Einheiten/Quelle und vermeiden Firmenzahl/Beschäftigung auf unpassend gemeinsamer Skala. Eine Berufserkundung kann nach konkreten Tätigkeiten, Qualifikationen und örtlichen Angeboten fragen; Aggregate allein sagen keine individuellen Chancen voraus.', 'Trade has more firms, manufacturing more employment relationships.7,801,230/198,362≈39.328 and6,017,332/538,248≈11.179. These means are neither typical-firm sizes nor unique-person counts. Linked charts show2024, units/definitions/source and avoid misleading combined scales. Exploration can ask about actual tasks, qualifications and local provision; aggregates do not predict individual chances.', 'Tatsächlich erzeugte datenverknüpfte Diagramme mit richtigen Daten/Bezügen2; zwei korrekt gerundete Mittelwerte und amtliche Abgrenzung2; begründeter Erkundungsschluss und Aggregat-/Personenzahlgrenze2. Ohne Spreadsheet-Arbeitsprodukt höchstens2 von6.', 'Actual linked charts with correct data/definitions2; two accurately rounded means/statistical boundary2; justified exploration conclusion and aggregate/person-count limitation2. Without spreadsheet artefact at most2of6.'),
        ('860ead33', 'Analysieren Sie alle vier Folienblöcke nach Zielgruppe, Aussagen, Belegen, Sprache und Darstellung. Verbessern Sie zwei konkrete Teile und erläutern Sie, welche Adressatenwirkung belegt bzw. noch offen ist.', 'Analyse all four blocks by audience, claims, evidence, language and display. Improve2specific parts and explain which audience effect is evidenced or uncertain.', 'Ausbildungssuchende brauchen Tätigkeiten, Lern-/Zugangsvoraussetzungen und nachvollziehbare Bedingungen, nicht starre Kreativitätszuweisung. Tabelle braucht Jahr, statistische Bedeutung und Quelle; Firmenzahl beweist keine Ausbildungsplatzzahl. Fachkürzel ohne Erklärung und unbelegte Erfolgsbehauptungen passen nicht zum Informationsbedarf. Verbesserungen etwa korrekt beschriftete Tabelle mit Grenze sowie verständliches Tätigkeitsbeispiel statt Kürzelsatz; Handlungsaufruf kann freiwilligen Informationsschritt nennen. Rückmeldung belegt nur diese fiktiv gegebene Perspektive, nicht garantierte Bewerbungen oder alle Zielgruppen.', 'Apprentices need tasks, learning/access conditions and reliable information, not fixed creativity allocation. The table needs year, statistical definition and source; firm counts are not training-place counts. Unexplained acronyms/unsupported success claims miss the audience need. Improve e.g. table labels/limitations and a clear job example; invite optional information seeking. Feedback supports only the stipulated perspective, not applications or universal effects.', 'Gesamte Präsentation entlang konkretem Adressatenbedarf und Beleg-/Sprach-/Darstellungskriterien2; zwei gezielte fachlich passende Verbesserungen2; Rückmeldung/Wirkungsbehauptung und stereotype Schlussgrenzen2.', 'Whole presentation against audience/evidence/language/display criteria2; two accurate specific improvements2; limits of feedback/effects and stereotypical conclusions2.'),
    ], [{'title':'Destatis: Statistisches Unternehmensregister2024;3August2026','url':'https://www.destatis.de/DE/Themen/Branchen-Unternehmen/Unternehmen/Unternehmensregister/Tabellen/stat-unternehmen-beschaeftigten-groessenklassen-wz08.html','use':'Two current factual rows and footnotes actually read from fresh200HTTP body. Earlier search cache still2023 is retained as diagnostic, not current factual material.'}])

add('youth-public-law',
    'E: Jugendfälle mit öffentlich-rechtlichen Regeln beurteilen', 'E: assess youth cases using public-law rules',
    'Die lernende Person kann fiktive jugendliche Handlungen anhand bereitgestellter Normen als Ordnungswidrigkeit oder Straftat analysieren, Tatbestandsmerkmale methodisch prüfen und Regelgestaltung sowie erzieherische Rechtsfolgen begründet beurteilen.',
    'The learner can analyse fictional youth conduct as an administrative offence or crime using supplied rules, examine offence elements methodically and assess rule design and educational legal consequences with reasons.',
    '''Alle Fälle sind erfunden; Tatsachen sind für die Aufgabe nachgewiesen. A: Eine16-Jährige hält während des Radfahrens ein Handy in der Hand und liest Nachrichten. Reife/Einsichts- und Steuerungsfähigkeit sowie Vorsatz liegen vor; keine Ausnahme. B: Ein15-Jähriger nimmt ein fremdes Fahrrad aus dem unverschlossenen Hof ohne Erlaubnis mit dem Vorsatz, es dauerhaft für sich zu behalten; fremder Gewahrsam wird gebrochen, keine Rechtfertigung, Reife gegeben. C: Derselbe Altersrahmen, aber ein anderer Ersttäter beschädigt vorsätzlich ein fremdes Fahrrad; Schaden nachgewiesen, keine Rechtfertigung, Reife gegeben. Er erkennt Unrecht und braucht Unterstützung bei Konfliktbewältigung; Opferinteressen und schulische Termine sind bekannt. Variante C2 stößt jemand das Fahrrad nur fahrlässig um; andere Straftatbestände sind ausgeschlossen.

Sinngemäße Norminformationen, Zugriff9.Oktober2026: [§23 Abs.1a StVO](https://www.gesetze-im-internet.de/stvo_2013/__23.html) verlangt bei elektronischer Gerätenutzung grundsätzlich kein Aufnehmen/Halten und zulässige Bedienung; passende kurze Blickzuwendung bzw. Sprachsteuerung wird differenziert behandelt, Stillstand besitzt eigene Regeln. [§49 Abs.1 Nr.22 StVO](https://www.gesetze-im-internet.de/stvo_2013/__49.html) verbindet vorsätzlichen/fahrlässigen Verstoß mit [§24 StVG](https://www.gesetze-im-internet.de/stvg/__24.html) als Ordnungswidrigkeit. [§12 OWiG](https://www.gesetze-im-internet.de/owig_1968/__12.html) schließt Vorwerfbarkeit unter14 aus und verlangt für Jugendliche die Reifevoraussetzungen des [§3 JGG](https://www.gesetze-im-internet.de/jgg/__3.html). Es wird keine Bußgeldhöhe geprüft.

[§242 StGB](https://www.gesetze-im-internet.de/stgb/__242.html) betrifft Wegnahme einer fremden beweglichen Sache mit rechtswidriger Zueignungsabsicht; [§303 Abs.1 StGB](https://www.gesetze-im-internet.de/stgb/__303.html) rechtswidrige Beschädigung/Zerstörung fremder Sachen. [§15 StGB](https://www.gesetze-im-internet.de/stgb/__15.html) verlangt Vorsatz, wenn Fahrlässigkeit nicht ausdrücklich strafbar ist; §303 enthält hier keine solche Fahrlässigkeitsstrafbarkeit. Unter14 besteht Schuldunfähigkeit nach [§19 StGB](https://www.gesetze-im-internet.de/stgb/__19.html). Jugendliche sind14bisunter18 nach [§1 JGG](https://www.gesetze-im-internet.de/jgg/__1.html); [§2 JGG](https://www.gesetze-im-internet.de/jgg/__2.html) richtet Rechtsfolgen vorrangig an Erziehung/Vermeidung weiterer Straftaten aus. [§5 JGG](https://www.gesetze-im-internet.de/jgg/__5.html) unterscheidet Erziehungsmaßregeln und bei deren Ungenügen Zuchtmittel/Jugendstrafe. [§10 JGG](https://www.gesetze-im-internet.de/jgg/__10.html) nennt zumutbare Weisungen wie sozialen Trainingskurs oder Bemühen um Täter-Opfer-Ausgleich; [§13 JGG](https://www.gesetze-im-internet.de/jgg/__13.html) nennt Verwarnung, Auflagen und Jugendarrest als Zuchtmittel ohne Rechtswirkungen einer Strafe. Ein automatischer Anspruch auf eine bestimmte Maßnahme oder eine pauschale Haftfolge wird nicht gegeben. Zivilrechtlicher Ersatz ist eine getrennte Frage und wird nicht berechnet.''',
    '''All cases are fictional; stipulated facts are established for the exercise. A: a16-year-old holds a phone and reads messages while cycling, with responsibility/maturity, intent and no exception. B: a15-year-old takes another\'s bicycle from an unlocked yard without permission to keep it permanently, breaking possession, without justification and with maturity. C: another first-time young offender intentionally damages a bicycle; damage, intent, maturity and lack of justification are established. The offender understands wrongdoing and needs conflict-management support; victim interests/school times are known. C2 merely knocks the bicycle over negligently; other offences are excluded.

Short paraphrases of German rules accessed9October2026: [StVO23(1a)](https://www.gesetze-im-internet.de/stvo_2013/__23.html) normally bars picking up/holding devices during use and distinguishes permitted control, brief suitable glances/voice and stationary exceptions. [StVO49(1)22](https://www.gesetze-im-internet.de/stvo_2013/__49.html) with [StVG24](https://www.gesetze-im-internet.de/stvg/__24.html) treats relevant intentional/negligent breaches as administrative offences. [OWiG12](https://www.gesetze-im-internet.de/owig_1968/__12.html) excludes responsibility under14 and requires [JGG3](https://www.gesetze-im-internet.de/jgg/__3.html) maturity for youths. No fine amount is assessed.

[StGB242](https://www.gesetze-im-internet.de/stgb/__242.html): taking another\'s movable property with unlawful appropriation intent. [StGB303(1)](https://www.gesetze-im-internet.de/stgb/__303.html): unlawful damage/destruction of another\'s property. [StGB15](https://www.gesetze-im-internet.de/stgb/__15.html) requires intent unless negligence is expressly criminalised, which303does not do here. [StGB19](https://www.gesetze-im-internet.de/stgb/__19.html) excludes criminal responsibility under14. [JGG1](https://www.gesetze-im-internet.de/jgg/__1.html) defines youths14tounder18; [JGG2](https://www.gesetze-im-internet.de/jgg/__2.html) prioritises education/preventing repeat offences. [JGG5](https://www.gesetze-im-internet.de/jgg/__5.html) distinguishes educational measures from disciplinary measures/youth sentence if education alone is insufficient. [JGG10](https://www.gesetze-im-internet.de/jgg/__10.html) provides reasonable directions, e.g. social training or efforts toward victim-offender mediation; [JGG13](https://www.gesetze-im-internet.de/jgg/__13.html) lists warning, conditions and youth detention as disciplinary measures without legal effects of a criminal sentence. No automatic measure or detention outcome is stipulated. Civil compensation is separate and not calculated.''',
    [
        ('537a6f0d', 'Analysieren Sie staatliche Folgen von A und C anhand der Norminformationen. Trennen Sie Ordnungswidrigkeit/Geldbuße, Jugendstraftat/erzieherische Reaktion und einen möglichen privaten Ersatzanspruch.', 'Analyse state consequences of A/C using the rules. Distinguish administrative offence/fine, youth crime/educational response and a possible private compensation claim.', 'A ist Fahrzeugführung mit gehaltenem/benutztem Handy ohne Ausnahme; bei gegebener Reife/Vorsatz liegt der bezeichnete Ordnungswidrigkeitsweg mit möglicher Geldbuße vor, keine dadurch festgestellte Straftat/Geldstrafe. C erfüllt nach Fakten vorsätzliche Sachbeschädigung, Jugendstrafrecht gilt; mögliche Folgen richten sich an Erziehung und den gesetzlichen Kategorien aus. Privater Ersatz ist gesondert zu prüfen und folgt nicht automatisch aus derselben staatlichen Sanktion; konkrete Höhe und Maßnahme sind offen.', 'A is device use while driving/riding, holding the phone without exception; responsibility/intent support the administrative-offence route and possible fine, not thereby a crime/criminal fine. C is intentional damage with juvenile rules applicable; consequences follow education and statutory categories. Private compensation needs separate examination, not the same state sanction; amount/measure remain open.', 'A regel-/faktenbezogen und richtige öffentlich-rechtliche Kategorie2; C mit Jugendstrafrechts-/Erziehungsbezug2; Geldbuße/Strafe und private Ersatzfrage getrennt, keine erfundene Höhe2.', 'A with rule/fact link and correct category2; C with juvenile/educational framework2; separate administrative/criminal fines and civil compensation, no invented amount2.'),
        ('b44892ea', 'Prüfen Sie B strukturiert nach Obersatz, Normmerkmalen, Subsumtion und Ergebnis, einschließlich Reife. Prüfen Sie C/C2 nach Vorsatz und Tatbestand. Wie ändert eine tatsächliche Eigentümererlaubnis in B die Prüfung?', 'Examine B by issue, statutory elements, application and conclusion, including maturity. Examine C/C2 for intent/elements. How would actual owner permission change B?', 'B: fremdes bewegliches Fahrrad, Bruch fremden Gewahrsams/Begründung eigenen, Wegnahme ohne Erlaubnis und Absicht dauerhafter rechtswidriger Zueignung; Vorsatz/keine Rechtfertigung und Jugend-/Reifeprüfung ergeben nach Fakten Diebstahl. Tatsächliche wirksame Erlaubnis zur Mitnahme/Dauerbehaltung würde die entsprechende Unrecht-/Wegnahmekonstellation ändern; nicht einfach gleiche Verurteilung. C vorsätzliche fremde Sachbeschädigung; C2 fehlt hier nötiger Vorsatz und keine Fahrlässigkeitsnorm303, daher insoweit keine Straftat. Zivile Folgen bleiben getrennt.', 'B: another\'s movable bicycle, breaking existing/creating own possession, taking without permission and intent to keep it unlawfully; intent, no justification and youth/maturity support theft under stipulated facts. Actual valid permission to take/keep would alter the relevant taking/unlawfulness situation, not leave an identical outcome. C intentionally damages another\'s property; C2 lacks required intent and303has no negligence offence here, so no crime on that basis. Civil effects remain separate.', 'Strukturierte fallbezogene B-Subsumtion mit entscheidenden242-Merkmalen2; Jugend/Reife und Erlaubnisvariation2; C/C2 nach15/303 fachlich getrennt2. Reine Normnummern ohne Subsumtion höchstens1 je Teil.', 'Structured fact-based B application of decisive242elements2; youth/maturity and permission variation2; correct C/C2 distinction under15/3032. Bare section numbers at most1 per part.'),
        ('d9a3db94', 'Beurteilen Sie für C sozialen Trainingskurs und Bemühen um Täter-Opfer-Ausgleich gegenüber pauschaler maximaler Bestrafung. Berücksichtigen Sie Erziehung, Zumutbarkeit und Opferinteressen; benennen Sie weiteren Prüfbedarf ohne gerichtlichen Ausgang vorwegzunehmen.', 'Assess social training/efforts at victim-offender mediation for C against blanket maximum punishment. Consider education, reasonableness/victim interests and further information without predetermining judgment.', 'Konkreter Konfliktlern-/Wiederholungspräventionsbedarf spricht für gezielte zumutbare Unterstützung und ernsthaften Ausgleichsversuch, soweit passend. Opferbeteiligung darf nicht als garantiert/frei von eigener Zustimmung behauptet werden. Schultermine und Belastung gehören zur Zumutbarkeit. Regeln unterscheiden Weisung, Zuchtmittel und Jugendstrafe; Ersttat oder Wiederholung erzwingen keine automatische Haft. Weitere Bedarfsermittlung und gesetzliche Voraussetzungen müssen geprüft werden; tatsächliche Wirkung wird nicht versprochen.', 'Conflict learning/prevention needs support tailored reasonable assistance and a genuine mediation effort where suitable. Victim participation is not guaranteed or imposed as fact. School timing/burden matter. Directions, disciplinary measures and youth sentence differ; first/repeat conduct does not automatically require detention. Needs/statutory conditions require examination, without promised efficacy.', 'Konkreter Erziehungs-/Präventionsmechanismus zweier Maßnahmen2; Zumutbarkeit und Opferinteressen2; rechtliche Kategorien, begründetes bedingtes Urteil/Prüfbedarf ohne automatische Haft2.', 'Specific educational/preventive mechanism of two measures2; reasonableness/victim interests2; legal categories and conditional assessment/checks without automatic detention2.'),
        ('61da4203', 'Beurteilen Sie Geräte- und Jugendaltersregeln nach Rechtsfunktionen, Gerechtigkeit und gesellschaftlichem Wandel. Entwickeln Sie eine begründete, kontrollierbare Regelidee oder Verbesserungsfrage ohne geltende Altersgrenzen zu verändern.', 'Assess device/youth age rules by legal functions, justice and social change. Develop a justified enforceable idea or improvement question without altering current age limits.', 'Geräteregel dient Schutz/Verkehrssicherheit und vorhersehbaren Verhaltensgrenzen; Differenzierung nach Halten/Bedienung/Stillstand muss mit Ablenkungsrisiko, praktischer Kontrolle und vergleichbaren Risiken begründet werden. Neue Navigationstechnik schafft Anpassungsfragen, keine pauschale Technikfeindlichkeit. Alters-/Reiferegeln verbinden Entwicklungsverantwortung/Erziehung und gleichartige Behandlung, bei legitimen Interessen Geschädigter; digitale Deliktsgelegenheiten beweisen keine Wirkung härterer Strafen. Vertretbare Idee etwa verständliche Bedienhinweise/Unterricht und Prüfung tatsächlicher Ablenkung/Wirksamkeit. Einzelfallgerechtigkeit und Kontrollierbarkeit sind Bedingungen; bestehende Grenzen bleiben dargestellt.', 'Device rules protect safety and predictable conduct; distinctions for holding/control/stationary use need attention to distraction, enforcement and similar risks. New navigation creates design questions, not blanket hostility to technology. Age/maturity rules connect development, education and comparable treatment while considering victims; digital opportunities do not prove harsher punishment works. Clear operating guidance/education and examination of actual distraction/effects are possible ideas. Individual justice/enforceability matter; current age rules remain stated.', 'Rechtsfunktionen beider Regelbereiche mit Materialbezug2; differenzierte Gerechtigkeit/Entwicklungs- und Wandelanalyse2; begründete kontrollierbare Idee/Prüffrage plus geltende Grenz-/Wirksamkeitstrennung2.', 'Functions of both rule areas with case links2; differentiated justice/development/change analysis2; justified enforceable idea/question and distinction from current limits/effect evidence2.'),
    ], [{'title':'Current German youth/public law, short own paraphrases','urls':['https://www.gesetze-im-internet.de/'+a for a in ['jgg/__1.html','jgg/__2.html','jgg/__3.html','jgg/__5.html','jgg/__10.html','jgg/__13.html','stgb/__15.html','stgb/__19.html','stgb/__242.html','stgb/__303.html','owig_1968/__12.html','stvo_2013/__23.html','stvo_2013/__49.html','stvg/__24.html']], 'use':'Norms actually read via current official web results or fresh HTTP fallback; no fine amount or sentencing prediction; private cases fictitious.'}])

add('participation-migration-and-networks',
    'E: Stadtteilwandel, Teilhabe und Netzwerke analysieren', 'E: analyse neighbourhood change, participation and networks',
    'Die lernende Person kann Perspektiven in einem fiktiven Stadtteildossier vergleichen, politische Sozialisation und soziale Netzwerke analysieren sowie Migration und wechselseitigen kulturellen Wandel nach begründeten Kriterien beurteilen.',
    'The learner can compare perspectives in a fictional neighbourhood dossier, analyse political socialisation and social networks, and assess migration and mutual cultural change against justified criteria.',
    '''Der erfundene Stadtteil Brückenhain gewinnt 100 neue Einwohner mit unterschiedlichen Qualifikationen, Altersgruppen und Aufenthaltsgeschichten. Für 40 fehlen passende Wohnungen; 25 möchten Sprachlernangebote nutzen, deren Abendkurs20 Plätze hat. Eine Werkstatt hat10 freie Stellen; bei sechs interessierten Personen sind vorhandene Qualifikationen noch nicht anerkannt. Die Zahlen beziehen sich auf unterschiedliche, möglicherweise überlappende Gruppen und dürfen nicht addiert werden.

Drei frei erfundene Stimmen: Nuri, neu zugezogen und berufserfahren, wünscht Anerkennungsberatung und geeignete Kinderbetreuung; Jo, seit Kindheit im Viertel, wünscht sichere Radwege und fragt nach frei zugänglichen Ausbildungsinformationen; Mila, ebenfalls neu zugezogen, spricht die Unterrichtssprache bereits und möchte einen Musikverein mitgestalten. Ein Stadtteilforum veröffentlicht Ausbildungsinformationen bisher nur in einer geschlossenen Kontaktgruppe; dort bestehen gegenseitige Hilfszusagen und Vertrauen. Eine offene digitale Liste hat500 Kontakte, aber bislang keine tatsächlich vermittelten Hilfen. Das Forum öffnet seine Informationen und bietet moderierte Treffen an.

Jo hört in Familie, Schule und Verein unterschiedliche Positionen zum Stadtteilbudget, prüft eigene Beispiele und ändert nach einer Diskussion ein Argument. Nuri bringt eine Veranstaltungsform ein; alte und neue Bewohner verändern sie gemeinsam, damit Termine, Sprache und Zugänge passen. Es gibt auch Bewohner, die keines dieser Angebote nutzen. Langfristige Wirkungen sind nicht erhoben.''',
    '''The invented neighbourhood Brückenhain gains100 residents with differing skills, ages and histories.40 lack suitable housing;25 want language classes, whose evening course has20 places. A workshop has10 vacancies; recognition remains unresolved for6 interested skilled people. The groups may overlap and must not be added.

Three invented voices: recently arrived, experienced Nuri wants qualification advice and suitable childcare; Jo, raised locally, wants safe cycle routes and open apprenticeship information; recently arrived Mila already speaks the teaching language and wants to help shape a music club. A forum shares apprenticeship information only in a closed group with trust and mutual support promises. An open list has500 contacts but no support actually delivered yet. The forum opens its information and offers facilitated meetings.

Jo hears different budget views in family, school and a club, examines examples and revises an argument after discussion. Nuri introduces an event format; established and new residents jointly adapt times, language and access. Some residents use none of the offers. Long-term effects have not been measured.''',
    [
        ('f79decb1', 'Rekonstruieren und vergleichen Sie die drei Stimmen nach genannten Bedürfnissen und Handlungsmöglichkeiten. Finden Sie zwei Gemeinsamkeiten und zwei Unterschiede, ohne Herkunft als feste Erklärung zu verwenden.', 'Reconstruct and compare the three voices by stated needs and opportunities. Find two similarities and two differences without using origin as a fixed explanation.', 'Nuri nennt konkrete Anerkennungs-/Betreuungsbedarfe; Jo Zugänglichkeit und Verkehrssicherheit; Mila aktive kulturelle Mitgestaltung. Alle wünschen praktikable Teilhabe, Jo und Nuri berufsbezogene Zugänge, Nuri und Mila jedoch unterschiedliche Sprach-/Qualifikationsbedingungen trotz Zuzug. Gemeinsamkeiten liegen quer zu Herkunft. Stimmen sind einzelne Perspektiven, keine repräsentativen Aussagen über alle Gruppen.', 'Nuri identifies recognition/care needs, Jo accessible information and safety, Mila cultural involvement. Practical participation is shared; Jo and Nuri share career-related needs, whereas Nuri and Mila differ despite both arriving recently. Similarities cross origins. Individual voices do not represent entire groups.', 'Alle drei Sichten mit Materialbezug2; zwei tragfähige Gemeinsamkeiten/Unterschiede2; Handlungsmöglichkeiten und Grenze der Gruppenverallgemeinerung2.', 'All three perspectives grounded in the dossier2; two sound similarities/differences2; opportunities and limits of group generalisation2.'),
        ('d7332142', 'Analysieren Sie Jos politische Sozialisation: Stellen Sie drei Einflüsse, deren Lern-/Interaktionswege und Jos aktive Rolle dar. Welche zusätzliche Handlungsmöglichkeit schafft das offene Forum?', 'Analyse Jo\'s political socialisation: identify three influences, their learning/interaction mechanisms and Jo\'s active role. What added opportunity does an open forum create?', 'Familie, Schule und Verein bieten unterschiedliche Deutungen, Gesprächsgelegenheiten und Beteiligungserfahrungen. Jo vergleicht Positionen mit Beispielen und revidiert ein Argument; Sozialisation ist Interaktion und aktive Verarbeitung, kein automatisch unveränderliches Erbe. Das offene Forum erweitert Informations- und Diskussionszugang, garantiert aber weder Teilnahme noch gleiche Überzeugungen.', 'Family, school and club provide different interpretations, discussion and participation experiences. Jo compares positions with examples and revises an argument; socialisation includes active processing rather than fixed inherited views. The open forum expands information/discussion access without guaranteeing participation or identical beliefs.', 'Drei konkrete Sozialisationsinstanzen und Wege2; aktive Verarbeitung/Änderung statt Determinismus2; neue Zugangschance und eine zutreffende Wirkungsgrenze2.', 'Three concrete agents/mechanisms2; active processing/change rather than determinism2; added access and valid limitation2.'),
        ('7a3f0ae8', 'Bewerten Sie gesellschaftliche und politische Chancen sowie Herausforderungen des Zuzugs anhand von Wohnen, Arbeit und Beteiligung. Priorisieren Sie eine Maßnahme mit zwei Kriterien und benennen Sie einen Prüfbedarf.', 'Assess social/political opportunities and challenges of arrival using housing, work and participation. Prioritise a measure with two criteria and identify a further information need.', 'Wohnraumknappheit40, Sprachplatzlücke5 und Anerkennungsfragen begrenzen Zugang; freie Stellen und vielfältige Erfahrungen eröffnen bedingte Chancen. Beratung könnte vorhandene Fähigkeiten mit den10 Stellen verbinden, garantiert aber keine Passung oder Einstellung. Eine priorisierte Wohn-/Sprach-/Anerkennungsmaßnahme braucht nachvollziehbare Kriterien wie Dringlichkeit, Zugang und Ressourcen; vertretbare Alternativen sind möglich. Überschneidungen, konkrete Qualifikationspassung und langfristige Teilhabe bleiben zu prüfen.', 'Housing shortages40, a5-place language gap and recognition issues constrain access; vacancies and varied experiences offer conditional opportunities. Advice could connect skills and10vacancies but cannot guarantee matching or hiring. Housing, language or recognition priorities need criteria such as urgency, access and resources; alternatives are acceptable. Overlap, actual skill fit and long-term participation need examination.', 'Je konkrete Chance und Herausforderung mit Daten2; gesellschaftlicher/politischer Wirkungsweg statt Herkunftsautomatismus2; begründete Priorität mit zwei Kriterien und passender weiterer Evidenz2.', 'Specific opportunity/challenge grounded in data2; social/political mechanism without origin determinism2; justified priority with two criteria and suitable further evidence2.'),
        ('3bf3a322', 'Erläutern Sie den Zusammenhang zwischen Migration, kulturellem Wandel und Integration am Veranstaltungsbeispiel. Vergleichen Sie Mitgestaltung mit bloßer Anwesenheit und benennen Sie zwei Zugangsbedingungen.', 'Explain migration, cultural change and integration using the event example. Compare joint shaping with mere presence and identify two access conditions.', 'Ein eingebrachter Impuls wird gemeinsam verändert; neue Praktiken entstehen durch wechselseitige Beteiligung, nicht durch die pauschale Anpassung einer homogenen Gruppe. Sprache, Termine und erreichbare Mitgestaltungsangebote beeinflussen Teilhabe. Anwesenheit allein beweist keine gleichberechtigte Mitgestaltung; Nichtteilnahme erklärt keine kulturelle Unwilligkeit, solange Bedürfnisse/Hürden unbekannt sind.', 'A new contribution is jointly adapted; practices develop through mutual participation, not one-way adjustment of a homogeneous group. Language, timing and reachable involvement matter. Presence alone is not equal influence, and nonattendance does not prove cultural unwillingness when needs/barriers are unknown.', 'Wechselseitiger kultureller Wirkungsweg mit Materialbezug2; Mitgestaltung/Anwesenheit sachlich getrennt2; zwei Zugangsbedingungen plus keine pauschale kulturelle Erklärung2.', 'Mutual cultural mechanism tied to the case2; distinguish shaping from presence2; two access conditions and no blanket cultural explanation2.'),
        ('bf851227', 'Vergleichen Sie geschlossenes Netzwerk und offene Kontaktliste als Sozialkapital. Beurteilen Sie Öffnung der Informationen und moderierte Treffen nach mobilisierbarer Hilfe, Vertrauen und Ausschlussrisiken.', 'Compare the closed network and open contact list as social capital. Assess open information and facilitated meetings by usable support, trust and exclusion risks.', 'Im geschlossenen Netzwerk bestehen aktivierbare Hilfen/Vertrauen, aber Informationsausschluss;500 Kontakte ohne vermittelte Hilfe beweisen kein höheres verfügbares Sozialkapital. Öffnung kann Informationszugang verbreitern, Treffen Vertrauen und konkrete gegenseitige Unterstützung fördern. Beides benötigt tatsächliche Beteiligung und zugängliche Angebote; Vertrauen/Arbeitsplatzvermittlung entstehen nicht automatisch. Eine offene verlässliche Vermittlungsstruktur kann Vorteile kombinieren.', 'The closed network has mobilisable support/trust but excludes others;500 contacts without delivered help do not prove greater usable social capital. Openness broadens information access and meetings may foster trust/support. Participation and accessibility remain conditions; neither trust nor placements are automatic. A reliable open referral structure could combine strengths.', 'Beziehungen, tatsächlich mobilisierbare Ressourcen und Vertrauen2; Ausschluss und Kontaktzahlgrenze2; fallbezogene Bewertung der Öffnung/Treffen mit Bedingung2.', 'Relationships, usable resources and trust2; exclusion and contact-count limitation2; case-based assessment of openness/meetings with a condition2.'),
    ])

add('online-consumption-bias-and-ethics',
    'E: Digitale Kaufentscheidungen und Verhaltenslenkung prüfen', 'E: examine digital purchases and behavioural influence',
    'Die lernende Person kann Gesamtkosten und Informationen eines fiktiven Onlinekaufs reflektieren, unterschiedliche Entscheidungsbias begründet anwenden und unternehmerische sowie politische Verhaltenslenkung ethisch beurteilen.',
    'The learner can reflect on total costs and information in a fictional online purchase, apply different decision-bias concepts with reasons, and ethically assess commercial and public behavioural influence.',
    '''Ein erfundener Shop bietet dieselbe Taschenlampe für42 EUR inklusive Versand wie ein örtlicher Laden für44 EUR. Lieferung online nach fünf Tagen; der Laden erlaubt unmittelbare Funktionsprüfung. Der Bedarf liegt am Folgetag. Ein anderes Onlineangebot wirbt mit36 EUR plus6 EUR Versand und zeigt80 gleichlautende Fünf-Sterne-Texte; Verkäuferinformationen sind unvollständig. Es werden keine gesetzlichen Rückgabefristen geprüft.

Varianten eines sonst gleichen Zusatzdienstes für ausdrücklich30 Tage: A lässt den bisherigen kostenpflichtigen Dienst voreingestellt; B verlangt aktive Wahl. C zeigt den gleichen Preis von42 EUR als1,40 EUR täglich, D als42 EUR für30 Tage; Leistungsumfang und Zeitraum sind gleich. E zeigt vor demselben Endpreis42 EUR einen behaupteten Vergleichspreis90 EUR, F nicht. Es liegen keine gemessenen Wirkungen vor. Ein Shop-Zusatz für6 EUR ist voreingestellt, die Abwahl versteckt. Eine alternative Gestaltung zeigt Preis, Zweck und leichte Abwahl offen.

Die fiktive Kommune stellt in der eigenen Kantine transparent ein pflanzliches Gericht als Standard bereit, um eine klimaverträglichere Verpflegung anzuregen. Andere Gerichte sind gleich einfach wählbar; Preise sind gleich. Unterschiedliche Bedürfnisse sind zu beachten. Eine Umweltwirkung ist nicht gemessen. Die Fälle beschreiben Unterrichtsmodelle, keine rechtliche Freigabe bestimmter Geschäftspraktiken.''',
    '''An invented shop offers the same torch forEUR42 including delivery as a local shop forEUR44. Online delivery takes5days; the local shop allows immediate testing. It is needed tomorrow. Another online offer advertisesEUR36 plusEUR6 delivery and80 identical five-star reviews; seller information is incomplete. Statutory return periods are not assessed.

Otherwise identical30-day add-on variants: A keeps an existing paid service selected, B needs active choice. C showsEUR1.40 daily, D EUR42 for30days with equal duration/service. E precedes the same EUR42 price with an alleged EUR90 reference price, F does not. No effects are measured. A shop selects aEUR6 add-on with hidden deselection; an alternative openly explains price/purpose and easy deselection.

The invented municipality transparently defaults to a plant-based meal in its canteen to encourage climate-compatible dining. Alternatives are equally easy to select at equal prices; needs differ. Environmental outcomes are not measured. These are teaching models, not legal approval of business practices.''',
    [
        ('d3c11bfa', 'Reflektieren Sie eine eigene Wahl im fiktiven Taschenlampenfall anhand von Bedarf, Gesamtkosten und überprüfbarer Information. Vergleichen Sie das zweite Onlineangebot, einschließlich der Bewertungen, und nennen Sie einen geeigneten Prüfschritt.', 'Reflect on a choice in the fictional torch case using need, total cost and verifiable information. Compare the second online offer, including reviews, and identify a suitable check.', '36+6=42 EUR ist nicht günstiger als das erste Onlineangebot; der örtliche Preis44 ist2 EUR höher, deckt aber den Bedarf am Folgetag und erlaubt Prüfung. Eine begründete örtliche Wahl ist unter diesem Zeitbedarf naheliegend; andere transparent begründete Prioritäten werden anerkannt. Gleichlautende Sterne und unvollständige Verkäuferangaben verlangen Prüfung echter Identität/Bedingungen oder begründeten Verzicht; Zahl der Bewertungen beweist keine Qualität. Persönliche Präferenz wird nicht bewertet, die nachvollziehbare Abwägung schon.', '36+6=42 is no cheaper than the first online offer; the local price44 is2higher but meets tomorrow\'s need and permits testing. Local purchase is justified under this deadline; other clearly justified priorities are acceptable. Identical reviews and incomplete seller data call for checking identity/conditions or abstaining; review count is not quality proof. Reasoning, not the personal preference, is assessed.', 'Beide korrekten Gesamtkosten und Bedarf-/Zeitbezug2; begründete Vor-/Nachteilsabwägung2; Bewertungs-/Verkäuferprüfung mit konkretem Prüfschritt2.', 'Correct total costs and need/timing2; justified advantage/disadvantage assessment2; review/seller scrutiny and concrete check2.'),
        ('84955a75', 'Erklären Sie, wie das Beibehalten des Zusatzdienstes und der Vergleichspreis Konsumentscheidungen beeinflussen könnten. Trennen Sie mögliche Mechanismen von nachgewiesenem individuellen Verhalten.', 'Explain how retaining the add-on and the reference price might influence purchases. Distinguish possible mechanisms from proven individual behaviour.', 'Voreinstellung/Wechselaufwand und begrenzte Aufmerksamkeit können Beibehaltung begünstigen; sie schließt bewusste Präferenz nicht aus.90 EUR kann als Anker die Bewertung desselben42-EUR-Produkts verschieben; die behauptete Vergleichsbasis ist außerdem prüfbedürftig. Ohne Daten sind dies Wirkungshypothesen. Kosten und Leistungsumfang müssen sonst gleich bleiben; nicht jeder Kauf ist ein Biasnachweis.', 'Default/switching effort and limited attention may favour retention without excluding deliberate preference.90 can anchor evaluation of the same42-priced product; the claimed reference also needs scrutiny. Without data these are hypotheses. Other costs/service must stay equal; a purchase alone is not proof of bias.', 'Zwei unterschiedliche konkrete Wirkungsmechanismen2; Kosten-/Leistungsgleichheit als Bedingung2; hypothesenbezogene Grenze und mögliche bewusste Präferenz2.', 'Two distinct concrete mechanisms2; equal cost/service as condition2; hypothetical status and possible deliberate preference2.'),
        ('eef95305', 'Ordnen Sie A/B, C/D und E/F Status-quo-Effekt, Framing und Anchoring zu. Begründen Sie jede Zuordnung mit dem veränderten Faktor. Entwerfen Sie für eine Paarung einen kontrollierten Vergleich.', 'Classify A/B, C/D and E/F as status-quo effects, framing and anchoring, explaining the changed factor. Design a controlled comparison for one pair.', 'A/B verändern die Ausgangsoption; C/D die äquivalente Darstellung bei1,40×30=42 und gleichem Zeitraum; E/F den vorangestellten Preisanker. Ein geeigneter Vergleich variiert nur diesen Faktor bei gleichen Produkten, Endpreisen, Laufzeiten und Informationsmöglichkeiten; Zuteilung/gleichartige Gruppen und beobachtete Wahl sind zu beschreiben. Kein Ergebnis wird vorab erfunden und unterschiedliche Produkte wären keine saubere Prüfung dieses Faktors.', 'A/B vary the initial option; C/D equivalent presentation with1.40×30=42 over equal duration; E/F the preceding price anchor. A controlled comparison changes only that factor, holding product, total price, duration and information fixed, with suitable assignment/comparable groups and observed choices. Results must not be invented; different products would confound the test.', 'Drei begründete mechanistische Zuordnungen3; korrekte Äquivalenz/Bezugsgröße1; tatsächlich kontrollierter Vergleich ohne Ergebnisbehauptung2.', 'Three justified classifications3; correct equivalence/denominator1; controlled comparison without invented outcome2.'),
        ('1d989a89', 'Vergleichen Sie Shop-Zusatz und kommunale Kantinenvoreinstellung nach Wirkungsweg, Interessen, Transparenz und Entscheidungsfreiheit. Begründen Sie eine ethische Grenze und eine überprüfbare Verbesserungs-/Evaluationsidee.', 'Compare the shop add-on and municipal canteen default by mechanism, interests, transparency and choice. Justify an ethical boundary and a testable improvement/evaluation.', 'Beide können Voreinstellung/Aufmerksamkeit nutzen, verfolgen aber Ertrag bzw. vorgegebenes öffentliches Klimaziel. Versteckte Kosten und schwer auffindbare Abwahl beeinträchtigen informierte Entscheidung; bloß formale Abwahl genügt nicht. Transparenz und gleich einfache Alternativen sind besser begründbar, müssen unterschiedliche Bedürfnisse berücksichtigen. Klimaabsicht beweist weder Wirkung noch automatisch ethische Zulässigkeit jeder Gestaltung. Offenlegung, einfache Auswahl und Prüfung von Verständlichkeit, tatsächlich freier Auswahl sowie Ergebnisdaten sind passende Ideen.', 'Both may use defaults/attention but pursue revenue versus a stated public climate aim. Hidden costs and hard-to-find deselection impair informed choice; formal opt-out alone is inadequate. Transparency and equally easy alternatives are more defensible while considering varied needs. Climate intent proves neither effects nor unconditional ethical acceptability. Disclosure, simple selection and checking understanding, actual choice and outcomes are suitable ideas.', 'Wirkungswege und unterschiedliche unternehmerische/politische Interessen2; Transparenz, Abwahl und Bedürfnisse fallbezogen2; begründete ethische Grenze plus überprüfbare Verbesserung/Evaluation2.', 'Mechanisms and different commercial/public aims2; case-based transparency, opt-out and needs2; justified ethical boundary and testable improvement/evaluation2.'),
    ])

add('competition-platform-and-market-failure',
    'E: Marktveränderung, Konzentration und Marktzugang untersuchen', 'E: examine market change, concentration and access',
    'Die lernende Person kann an einem fiktiven Reparaturmarkt Unternehmensreaktionen, Konzentrations- und Plattformwirkungen analysieren, Formen von Marktversagen erklären und begründete Wettbewerbseingriffe vergleichen.',
    'The learner can analyse firm responses, concentration and platform effects in a fictional repair market, explain forms of market failure and compare justified competition interventions.',
    '''Alle Firmen, Zahlen und Regeln sind didaktische Modellannahmen. Zwei unabhängige regionale Reparaturketten A/B bedienen zusammen80% der Aufträge. Zwei kleinere Werkstätten teilen20%; Eintritt erfordert teure Spezialgeräte. A/B erwägen eine Fusion: gemeinsame Diagnosegeräte könnten je Auftrag5 EUR Kosten sparen. Die Weitergabe ist nicht zugesagt. Separat zeigen nachgewiesene interne Absprachen dreier noch unabhängiger Firmen über Mindestpreise; zufällig gleiche Preise werden ausdrücklich nicht behauptet.

Kunden verlangen vermehrt länger nutzbare, reparierbare Geräte. Ein Hersteller kann für3 EUR Mehrkosten Ersatzteilzugang verbessern oder für1 EUR nur die Werbung verändern. Eine Onlineplattform verbindet Kundschaft und Werkstätten, erhebt10% Gebühr und beeinflusst Suchrangfolgen. Viele Teilnehmende verbessern die Vermittlung; bestehende Bewertungen lassen sich nicht übertragen. Eine notwendige Schnittstelle ist für neue Werkstätten gesperrt. Vorgeschlagen sind offene überprüfbare Zugangskonditionen, bloße Werbung für kleine Werkstätten, Veräußerung eines tatsächlich selbstständigen Betriebsbereichs bei Fusion oder Fusionsuntersagung.

Weitere Marktbausteine im selben Stadtgebiet: Bei gebrauchten Geräten kennen Verkäufer die Qualität, Käufer nicht; Käufer bieten einen Durchschnittspreis, bei dem hochwertige Anbieter möglicherweise ausscheiden. Ein gemeinsam empfangenes, zusätzlich nutzbares Hochwasserwarnsignal ist nach Bereitstellung im Modell nicht ausschließbar und nicht rivalisierend. Ein örtlicher Monopolanbieter ist vor Eintritt geschützt. Vereinfachte Modellregel: wettbewerbsbeschränkende Preisabsprache untersagt; Fusionen werden vorab nach Alternativen, Eintritt und belegbaren Effizienzen geprüft. Eine große Firma oder identische Preise allein beweisen keinen Verstoß.''',
    '''All firms, numbers and rules are teaching-model assumptions. Independent repair chains A/B jointly handle80% of orders; two small workshops share20%, while entry needs costly specialist equipment. A/B consider merging; shared diagnostic equipment could saveEUR5per order without promised pass-through. Separately, proven internal records show minimum-price coordination among three still-independent firms, not merely coincident prices.

Customers increasingly want durable, repairable devices. A manufacturer can improve spare-part access forEUR3 extra cost or change only advertising forEUR1. A platform connects customers/workshops, charges10% and controls rankings. More participants improve matching; reviews cannot transfer. A necessary interface excludes entrants. Proposed measures are verifiable open access, advertising small workshops, disposal of an actually independent business unit during merger, or prohibition.

In the same area sellers know used-device quality but buyers do not; average offers may drive good suppliers out. A flood-warning signal is non-excludable and non-rival once provided. A local monopolist is protected from entry. Simplified model rule: restrictive price coordination is prohibited; merger review examines alternatives, entry and credible efficiencies. Size or identical prices alone proves no breach.''',
    [
        ('5ccb466f', 'Analysieren Sie die beiden Herstellerreaktionen auf veränderte Nachfrage nach reparierbaren Geräten. Verbinden Sie Angebot, Kosten und mögliche Absatzwirkung und begründen Sie ein bedingtes Vorgehen.', 'Analyse the manufacturer\'s two responses to changing demand for repairable devices. Link offering, costs and possible demand, justifying a conditional approach.', 'Verbesserter Ersatzteilzugang verändert tatsächlich Nutzbarkeit/Reparaturmöglichkeit und kostet3 EUR; reine Werbung kostet1 EUR, schafft die Leistung aber nicht. Bei entsprechender Zahlungsbereitschaft/Nachfrage kann der Mehrnutzen die höhere Belastung rechtfertigen; Absatz und Wettbewerb bleiben zu prüfen. Werbung kann informieren, wenn ihr Gegenstand zutrifft, ersetzt jedoch keine Produktanpassung. Eine datenbezogene bedingte Empfehlung benötigt Pilotnachfrage, Kosten- und Lieferfähigkeit statt sicheren Erfolg.', 'Spare-part access changes actual repairability for3; advertising for1 does not create it. Relevant willingness to pay/demand may justify costs, but sales and rivalry need checking. Accurate advertising may inform without replacing adaptation. A conditional recommendation needs pilot demand, cost and supply feasibility rather than guaranteed success.', 'Konkreter Nachfrage-/Reaktionsbezug2; tatsächliche Leistung versus Kommunikation und Kosten2; bedingte Absatz-/Durchführungsabwägung mit Prüfbedarf2.', 'Specific demand/response link2; actual service versus communication and costs2; conditional demand/feasibility assessment with information need2.'),
        ('cb21bcbe', 'Erläutern Sie Chancen und Risiken der Fusion A/B anhand von Gerätenutzung, Preisen, Qualität und Ausweichmöglichkeiten. Welche Aussage erlauben die5 EUR Kostenvorteil nicht?', 'Explain merger opportunities and risks using equipment, prices, quality and alternatives. What does theEUR5 saving not establish?', 'Geteilte Geräte können Auslastung und Stückkosten verbessern; A/B fallen als unabhängige Alternativen weg.80% gemeinsamer Anteil, kleinere Restanbieter und teurer Eintritt begründen konkrete Marktmacht-/Qualitätsrisiken. Kostenersparnis bedeutet nicht automatisch niedrigeren Preis oder bessere Qualität; verbleibende Wechseloptionen und tatsächlich realisierbare Vorteile müssen geprüft werden. Anteil allein ist im Modell kein automatisches Verbot.', 'Shared equipment may improve utilisation/cost; A/B cease being independent alternatives.80%share, limited remaining rivals and costly entry give specific market-power/quality concerns. Savings do not guarantee lower prices or quality; real alternatives and credible gains need scrutiny. Share alone is not automatic prohibition.', 'Nachvollziehbarer Effizienzvorteil2; zwei konkrete Wettbewerbs-/Qualitätsrisiken2; Preisweitergabe-/Alternativengrenze ohne automatisches Größenverbot2.', 'Coherent efficiency advantage2; two concrete competition/quality risks2; limits of pass-through/alternatives without automatic size prohibition2.'),
        ('af709beb', 'Vergleichen Sie Fusionsuntersagung mit unabhängiger Veräußerung und offenen Schnittstellen mit Werbung. Empfehlen Sie für jedes Problem eine passende Maßnahme mit einer Umsetzungsbedingung.', 'Compare merger prohibition with independent disposal, and open interfaces with advertising. Recommend a suitable measure for each problem with an implementation condition.', 'Untersagung erhält A/B-Selbstständigkeit, kann gemeinsame Gerätevorteile verhindern; wirkliche Veräußerung kann Konkurrenz bei Teilen der Effizienz erhalten, wenn Käufer unabhängig und dauerhaft handlungsfähig ist. Offene Schnittstelle bearbeitet die konkrete Eintrittssperre; Werbung allein öffnet sie nicht. Konditionen, Durchsetzung und technische Nutzbarkeit müssen kontrollierbar sein. Unterschiedliche vertretbare Empfehlungen erhalten Punkte bei belegtem Problem-/Instrumentbezug.', 'Prohibition preserves independent rivalry but may lose shared-equipment gains; disposal can retain competition and some efficiencies if the buyer is independent/viable. Open access addresses the actual barrier; advertising does not. Conditions, enforcement and technical usability must be verifiable. Different defensible recommendations receive credit when tied to mechanisms.', 'Zwei richtige problembezogene Instrumentvergleiche2; Effizienz-/Wettbewerbs-/Zugangswirkung2; je passende Empfehlung und konkrete Umsetzungsbedingung2.', 'Two correct problem-based comparisons2; efficiency/competition/access mechanisms2; suitable recommendations and implementation conditions2.'),
        ('21dc877b', 'Unterscheiden und begründen Sie Eingriffe bei nachgewiesener Preisabsprache und geplanter Fusion nach der Modellregel. Welche Information verhindert eine bloß pauschale Beurteilung?', 'Distinguish and justify action on proven price coordination and the planned merger under the model rule. What information prevents a blanket judgment?', 'Absprache schaltet selbstständige Preisentscheidung zwischen weiter getrennten Firmen aus und ist nach der gegebenen Regel zu beenden. Fusion ändert Struktur; vorausschauende Kontrolle prüft Verlust von Alternativen gegen Eintritt und belegte Effizienz. Gleicher Preis allein ist kein Absprachebeweis und große Firma allein kein Fusionsverstoß. Tatsächliche Kommunikation/Unabhängigkeit, erreichbare Alternativen und Eintrittsbedingungen tragen die Begründung.', 'Coordination removes independent pricing among separate firms and must end under the supplied rule. Merger changes structure; prospective review weighs lost alternatives, entry and credible efficiencies. Equal prices alone do not prove coordination; size alone does not establish a prohibited merger. Actual communications, independence, alternatives and entry are relevant.', 'Absprache versus struktureller Zusammenschluss2; je begründeter Wettbewerbsbezug und Eingriff2; konkrete benötigte Fakten und Grenzen pauschaler Schlüsse2.', 'Coordination versus structural combination2; justified competition concern/intervention for each2; specific facts and limits of blanket inference2.'),
        ('1826fe19', 'Erklären Sie alle drei beschriebenen Marktversagensmechanismen: Gebrauchtgeräte, Warnsignal und geschütztes Monopol. Verbinden Sie jeweils Fallannahme und mögliche ineffiziente Folge.', 'Explain all three market-failure mechanisms: used devices, warning signal and protected monopoly. Link each assumption with its possible inefficient consequence.', 'Ungleiches Qualitätswissen und Durchschnittspreis können gute Angebote verdrängen, nicht bloß jede Informationsdifferenz. Nichtausschließbarkeit/Nichtrivalität begünstigen Trittbrettfahren und Unterfinanzierung des Signals; rivalisierender Wasserverbrauch wäre anders. Geschützte Marktmacht kann höheren Preis und geringere Menge begünstigen, weil Konkurrenz/Eintritt fehlen. Es sind bedingte Mechanismen, keine gemessenen Ergebnisse des Stadtgebiets.', 'Quality asymmetry and average prices may drive good suppliers out, rather than every knowledge difference being failure. Non-excludability/non-rivalry enable free riding and underfunding; rival water consumption differs. Protected market power can favour higher prices/lower quantities without entry/rival pressure. These are conditional mechanisms, not measured local outcomes.', 'Je Form mit korrekt fallbezogenem Mechanismus und Folge2; insgesamt6. Bloße Etiketten ohne Mechanismus höchstens je1.', 'Each form with correct case-based mechanism/consequence2, total6. Labels alone at most1 each.'),
        ('52e6731e', 'Analysieren Sie die Digitalisierungswirkungen der Plattform für Werkstätten und Kundschaft. Beurteilen Sie Reichweite, Netzwerkeffekte, Gebühren, Rangfolgen und Wechselhürden; formulieren Sie ein bedingtes Urteil.', 'Analyse platform digitalisation for workshops and customers. Assess reach, network effects, fees, rankings and switching barriers, stating a conditional conclusion.', 'Vermittlung senkt Suchkosten und erweitert Reichweite;10%-Gebühr belastet Anbietererlöse. Mehr Teilnehmer können den Vermittlungsnutzen erhöhen, ohne Wettbewerb zu garantieren. Nichtübertragbare Bewertungen und kontrollierte Rankings schaffen Bindung, Abhängigkeit und Informationsrisiken. Transparente Rangfolgen, Alternativen und Wechselmöglichkeiten sind Urteilskriterien; bloß mehr sichtbare Anbieter beweist keine wirksame Konkurrenz.', 'Matching reduces search costs and expands reach;10%fees reduce supplier receipts. More users may increase matching value without guaranteeing competition. Nontransferable reviews/rank control create lock-in, dependence and information risks. Transparent rankings, alternatives and switching are criteria; more visible sellers alone does not prove effective rivalry.', 'Anbieter-/Nachfragerchancen mit Mechanismus2; Netzwerkeffekt, Gebühren und konkrete Wechsel-/Informationsrisiken2; kriterienspezifisches bedingtes Urteil und Wettbewerbsgrenze2.', 'Supplier/customer opportunities with mechanisms2; network effects, fees and concrete switching/information risks2; conditional criteria-based judgment and competition limitation2.'),
    ])


